var Q26 = [
  {n:1,q:'La función pública local se rige:',o:{a:'Por la legislación estatal.',b:'Por la legislación de las Comunidades Autónomas.',c:'Por la normativa local.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'El art. 3.1 EBEP establece que «el personal funcionario de las Entidades Locales se rige por la legislación estatal que resulte de aplicación, de la que forma parte este Estatuto y por la legislación de las Comunidades Autónomas, con respeto a la autonomía local». Asimismo, las entidades locales podrían jurídicamente desarrollar ámbitos determinados del EBEP.'}},
  {n:2,q:'El Real Decreto Legislativo 5/2015, de 30 de octubre, por el que se aprueba el texto refundido de la Ley del Estatuto Básico del Empleado Público (desde ahora EBEP) se considera legislación básica de:',o:{a:'El régimen jurídico de los funcionarios públicos locales.',b:'El régimen jurídico de los empleados laborales públicos locales.',c:'El régimen jurídico de los funcionarios públicos locales y de los empleados laborales públicos locales.',d:'El régimen jurídico de los funcionarios públicos locales, de los empleados laborales públicos locales y de los trabajadores por cuenta propia.'},correct:'c',why:{'c':'El EBEP es la legislación básica del régimen jurídico de los funcionarios públicos (incluyendo a los funcionarios públicos locales) y, por otro, legislación de la relación laboral especial de empleo público de la Administración (incluida la Administración Local). La denominación «empleado público» engloba en abstracto a quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales (art. 8.1 EBEP).'}},
  {n:3,q:'Los cuerpos de la Policía Local se rigen en materia de función pública:',o:{a:'Por el Estatuto Básico del Empleado Público.',b:'Por la Ley Orgánica de Fuerzas y Cuerpos de Seguridad.',c:'Por la legislación sectorial de las Comunidades Autónomas.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'Los cuerpos de la Policía Local, de acuerdo con el art. 3.2 EBEP, «se rigen también por este Estatuto y por la legislación de las Comunidades Autónomas, con excepción de lo previsto en la Ley Orgánica 2/1986, de 13 de marzo, de Fuerzas y Cuerpos de Seguridad».'}},
  {n:4,q:'¿Cómo se denomina a los empleados públicos que en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente?',o:{a:'Funcionarios interinos.',b:'Funcionarios de carrera.',c:'Funcionarios al servicio de las administraciones públicas.',d:'Funcionarios públicos.'},correct:'b',why:{'b':'El art. 9 del EBEP dispone que «son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente».'}},
  {n:5,q:'¿Qué tipo de funciones corresponden exclusivamente a los funcionarios públicos?',o:{a:'El ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones Públicas.',b:'El ejercicio de funciones relacionadas directa o indirectamente con la autoridad.',c:'El ejercicio de funciones relacionadas con la fe pública.',d:'El ejercicio de cualesquiera funciones económicas y financieras.'},correct:'a',why:{'a':'El art. 9.2 del EBEP establece que «en todo caso, el ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones Públicas corresponden exclusivamente a los funcionarios públicos».'}},
  {n:6,q:'Los funcionarios de carrera de la Administración local se dividen en:',o:{a:'Funcionarios propios y funcionarios interinos.',b:'Funcionarios propios y funcionarios con habilitación de carácter nacional.',c:'Funcionarios interinos y funcionarios públicos.',d:'Funcionarios propios y funcionarios impropios.'},correct:'b',why:{'b':'Los funcionarios de carrera de la Administración Local se dividen en dos grandes grupos: funcionarios con habilitación de carácter nacional y los funcionarios propios de la Corporación. Según el art. 92 bis.2 LBRL, la escala de funcionarios con habilitación se subdivide en: Secretaría, Intervención-tesorería y Secretaría-intervención.'}},
  {n:7,q:'¿Podrían las funciones de contabilidad, tesorería y recaudación atribuidas a funcionarios habilitados de carácter nacional ser ejercidas por un Concejal o funcionario de la Corporación?',o:{a:'No, ya que la Ley atribuye estas funciones a funcionarios habilitados.',b:'No, ya que las funciones de contabilidad, tesorería y recaudación exigen la dación de fé pública.',c:'Sí, en cualquier Municipio, si así se aprueba por el Pleno.',d:'Sí, de forma excepcional de acuerdo con lo que determine la legislación del Estado.'},correct:'d',why:{'d':'Con la entrada en vigor del Real Decreto-Ley 10/2015 las funciones de Tesorería y Recaudación pueden ser encomendadas a Secretarios-Interventores, prohibiéndolo a quienes carecían de habilitación legal. No pueden ser desempeñadas por Concejales desde la entrada en vigor de dicha norma.'}},
  {n:8,q:'¿Qué clase de personal podrá ser llamado a desempeñar temporalmente puestos de trabajo asignados a funcionarios de carrera?',o:{a:'Personal laboral fijo.',b:'Personal laboral temporal.',c:'Funcionarios interinos.',d:'Personal eventual.'},correct:'c',why:{'c':'Los funcionarios interinos, que el art. 10.1 EBEP caracteriza como «los que, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales para el desempeño de funciones propias de funcionarios de carrera». Su cese se produce cuando finalice la causa que dio lugar a su nombramiento (art. 10.3 EBEP).'}},
  {n:9,q:'Los criterios para la determinación de los puestos de trabajo que pueden ser desempeñados por personal laboral se establecen:',o:{a:'En la Constitución Española.',b:'En el EBEP.',c:'En las Leyes estatales o autonómicas de función pública que se dicten como desarrollo del EBEP.',d:'En las disposiciones reglamentarias de función pública de las Comunidades Autónomas.'},correct:'c',why:{'c':'El art. 11.2 del EBEP establece que serán las leyes de función pública que se dicten en desarrollo del EBEP las que establecerán los criterios para la determinación de los puestos de trabajo que pueden ser desempeñados por personal laboral.'}},
  {n:10,q:'El apoyo a los titulares de cargos políticos se realiza mediante:',o:{a:'Personal funcionario.',b:'Personal directivo.',c:'Personal eventual.',d:'Personal laboral.'},correct:'c',why:{'c':'El personal eventual es la denominación con la que se conoce a las personas que apoyan a los titulares de cargos políticos en funciones «expresamente calificadas como de confianza o asesoramiento especial» (art. 12.1 EBEP). Su nombramiento y cese son enteramente libres, cesando cuando cese la autoridad a la que se presta la función.'}},
  {n:11,q:'El personal laboral al servicio de las Corporaciones Locales se clasifica en:',o:{a:'Personal laboral fijo, personal laboral temporal y personal laboral indefinido no fijo.',b:'Personal laboral fijo y personal laboral eventual.',c:'Personal laboral eventual y personal laboral indefinido.',d:'Personal laboral fijo y personal laboral temporal.'},correct:'a',why:{'a':'Fruto de la jurisprudencia, en el empleo público hay que distinguir entre personal laboral fijo (superó proceso selectivo respetando igualdad, mérito y capacidad), personal laboral temporal (contrato temporal) y personal laboral indefinido no fijo (creación jurisprudencial del Tribunal Supremo para quienes no superaron procedimientos selectivos).'}},
  {n:12,q:'El personal eventual:',o:{a:'Sólo podrá prestar servicio a aquellas concretas autoridades que se mencionen en las leyes de función pública dictadas en su desarrollo.',b:'Habrá de determinarse normativamente el número máximo de que podrá disponer cada tipo de órgano o autoridad.',c:'Sus condiciones retributivas serán públicas.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'El EBEP en su art. 12.2 y 4 ha establecido: 1) que el personal eventual solo podrá prestar servicio a aquellas concretas autoridades que se mencionen en las leyes de función pública dictadas en su desarrollo; 2) que habrá de determinarse normativamente el número máximo de personal eventual; 3) que dicho número máximo y las retribuciones que perciba serán públicas.'}},
  {n:13,q:'El nombramiento del personal eventual se realiza:',o:{a:'De forma absolutamente libre.',b:'Por el sistema de libre designación.',c:'Por concurso de méritos.',d:'Por concurso-oposición.'},correct:'a',why:{'a':'El nombramiento y cese del personal eventual son absolutamente libres en cuanto se basan única y exclusivamente en criterios de confianza. Para su nombramiento no es preciso utilizar el sistema de libre designación con convocatoria pública al que se refiere el art. 80 del EBEP.'}},
  {n:14,q:'El personal directivo profesional requiere:',o:{a:'La previa pertenencia al colectivo de funcionarios de carrera.',b:'La previa pertenencia al sector público.',c:'La sujeción a resultados concretos en relación con los objetivos que les hayan sido fijados.',d:'El nombramiento de forma libre.'},correct:'c',why:{'c':'El personal directivo profesional estará sujeto a «evaluación con arreglo a los criterios de eficacia y eficiencia, responsabilidad por su gestión y control de resultados en relación con los objetivos que les hayan sido fijados». No se exige previa pertenencia a ningún colectivo de empleados públicos.'}},
  {n:15,q:'El personal directivo se diferencia del personal eventual:',o:{a:'Por las funciones que realiza.',b:'Por su forma de designación.',c:'Por la forma en la que se produce su cese.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'Atendiendo a los artículos 12 y 13 del EBEP, el personal directivo se diferencia del eventual por sus funciones, su forma de designación y la responsabilidad en el ejercicio de sus funciones (el directivo está sujeto a evaluación de eficacia y eficiencia, mientras que para el eventual su cese será libre).'}},
  {n:16,q:'El personal eventual ¿se puede incluir en la plantilla de cualquier entidad local?',o:{a:'Sí, mientras que se asignase a los servicios generales de las Entidades Locales en cuya plantilla aparezca consignado.',b:'Sí, aunque su nombramiento y cese no sea libre.',c:'No, ya que ciertas entidades locales tienen vedado incluirlo en sus plantillas.',d:'Sí, incluyendo las Mancomunidades, Áreas Metropolitanas y Comarcas.'},correct:'d',why:{'d':'La STC 54/2017, de 11 de mayo, declaró inconstitucionales y nulos los apartados 3 y 4 del art. 104 bis LBRL que prohibían a Mancomunidades, Áreas Metropolitanas y Comarcas incluir personal eventual en sus plantillas, por penetrar en la organización interna de las corporaciones locales y no admitir adaptaciones autonómicas.'}},
  {n:17,q:'El nombramiento del personal interino de las corporaciones locales estará justificado por razones:',o:{a:'De especial confianza y asesoramiento.',b:'De necesidad o urgencia de las tareas a desarrollar.',c:'Técnicas y profesionales.',d:'Ninguna respuesta es correcta.'},correct:'b',why:{'b':'El nombramiento del personal interino debe estar justificado por razones de necesidad o urgencia (art. 10 EBEP y 5.2 LFCE). No pueden nombrarse funcionarios interinos para atender situaciones normales en la Función Pública.'}},
  {n:18,q:'¿Cuál de las siguientes respuestas sobre los funcionarios interinos de las corporaciones locales no es correcta?',o:{a:'Deben ocupar plazas de plantillas dotadas presupuestariamente.',b:'Deben ocupar plazas que correspondan a funcionarios de carrera.',c:'Deben ocupar plazas que ya existen, pero que se encuentran vacantes.',d:'Se pueden crear nuevas plazas para ser cubiertas por funcionarios interinos.'},correct:'d',why:{'d':'Es inadmisible la creación de determinadas plazas para ser cubiertas por funcionarios interinos, así como el nombramiento de interinos sin existencia previa de plaza vacante. Los funcionarios interinos deben ocupar plazas de plantillas dotadas presupuestariamente, esto es, plazas que ya existen pero que se encuentran vacantes.'}},
  {n:19,q:'El funcionario interino ¿tiene derecho a la reserva de la plaza y el puesto que está ocupando?',o:{a:'Sí, pudiendo equipararse en estos derechos con los funcionarios de carrera.',b:'Sí, sin que pueda existir desigualdad de trato respecto a los funcionarios de carrera.',c:'No, ya que la plaza se ocupa de manera provisional.',d:'Sí, pudiendo desarrollar incluso funciones que implican ejercicio de autoridad.'},correct:'c',why:{'c':'En general, el funcionario interino no tiene derecho alguno a la plaza y puesto que provisionalmente está ocupando, pues está reservada a un funcionario de carrera. Puede considerarse irregular que los funcionarios interinos desempeñen funciones que impliquen ejercicio de autoridad, incluyendo las de jefatura (art. 92.2 LBRL).'}},
  {n:20,q:'¿Cuál de las siguientes respuestas respecto de los funcionarios interinos no es cierta?',o:{a:'La Administración que designa al funcionario interino lo puede cesar cuando finalice la causa que dio lugar a su nombramiento.',b:'Disfrutan del derecho a la protección por desempleo.',c:'Se les reconoce el derecho a computar trienios.',d:'La Administración puede cesar al funcionario interino discrecionalmente.'},correct:'d',why:{'d':'El cese del funcionario interino no es absolutamente libre o discrecional para la Administración sino que se supedita legalmente a la concurrencia de una de las dos condiciones: la provisión del puesto por funcionario de carrera o la desaparición de las razones de necesidad y urgencia que motivaron el nombramiento (art. 10.3 EBEP).'}},
  {n:21,q:'No corresponde al Alcalde en materia de personal en los municipios de régimen ordinario:',o:{a:'Aprobar la oferta de empleo público.',b:'Desempeñar la jefatura superior de todo el personal.',c:'Aprobar la plantilla de personal y la relación de puestos de trabajo.',d:'Acordar el nombramiento de los funcionarios de la Corporación.'},correct:'c',why:{'c':'La aprobación de la plantilla de personal y la relación de puestos de trabajo corresponde al Pleno de la Corporación (art. 22.2.i LBRL). Tras la reforma de la LBRL por la Ley 11/1999, el Alcalde tiene atribuida la aprobación de la oferta de empleo público, las bases de convocatorias, la jefatura del personal y el acuerdo de nombramiento y sanciones.'}},
  {n:22,q:'Corresponde al Alcalde en materia de personal en los municipios de régimen ordinario:',o:{a:'Aprobar las bases de las pruebas para la selección del personal.',b:'Fijar la cuantía de las retribuciones complementarias.',c:'Determinar el número y régimen del personal eventual.',d:'Fijar la cuantía de las retribuciones periódicas.'},correct:'a',why:{'a':'El art. 21 de la LBRL atribuye al Alcalde aprobar las bases de las pruebas para la selección del personal y para los concursos de provisión de puestos de trabajo. Sin embargo, la fijación de la cuantía de las retribuciones complementarias fijas y periódicas y el número y régimen del personal eventual corresponde al Pleno (art. 22.2.i LBRL).'}},
  {n:23,q:'En los municipios de gran población la oferta de empleo público es aprobada por:',o:{a:'El Pleno.',b:'El Alcalde.',c:'La Junta de Gobierno Local.',d:'La Diputación Provincial.'},correct:'c',why:{'c':'En los municipios regidos por el Título X de la LBRL, el art. 127 atribuye a la Junta de Gobierno Local aprobar la oferta de empleo público, la relación de puestos de trabajo, las bases de las convocatorias de selección y provisión de puestos de trabajo, el número y régimen del personal eventual, entre otras.'}},
  {n:24,q:'Los cuerpos y escalas de funcionarios se crean, modifican y suprimen:',o:{a:'Por Ley de las Cortes Generales.',b:'Por Ley de las Cortes Generales o de las Asambleas Legislativas de las Comunidades Autónomas.',c:'Por la legislación básica estatal en materia de función pública.',d:'Por disposiciones legislativas o reglamentarias.'},correct:'b',why:{'b':'El art. 75.2 del EBEP establece que «los cuerpos y escalas de funcionarios se crean, modifican y suprimen por Ley de las Cortes Generales o de las Asambleas Legislativas de las Comunidades Autónomas». Esta reserva de ley actúa como freno a posibles presiones para elevar el nivel de titulación exigido para el ingreso.'}},
  {n:25,q:'De acuerdo con el EBEP la posesión del título universitario de grado se exigirá a los funcionarios:',o:{a:'Del grupo A.',b:'Del subgrupo A2.',c:'Del grupo B.',d:'De los subgrupos C1 y C2.'},correct:'a',why:{'a':'El art. 76 EBEP clasifica los Cuerpos y Escalas en tres grupos A, B y C. Para el acceso al Grupo A se exige estar en posesión del título universitario de Grado; este Grupo se subdivide en los Subgrupos A1 y A2. Para el Grupo B se exige el título de Técnico Superior y para el Grupo C el de bachiller/técnico (C1) o graduado en ESO (C2).'}},
  {n:26,q:'Los funcionarios propios de las Corporaciones locales se integran en la actualidad:',o:{a:'Por la Escala de Administración General y la Escala de Administración Especial.',b:'Por la Escala de Administración General y la Escala de Servicios Especiales.',c:'Por la Escala de Administración General, la Escala de Administración Especial y la Escala de Servicios Especiales.',d:'Por la Escala de Administración General, la Escala de Administración Especial, la Escala de Servicios Especiales y la Escala Técnica.'},correct:'a',why:{'a':'Los funcionarios de carrera de las Corporaciones Locales que no tengan habilitación de carácter nacional se integran en las escalas de Administración General y Administración Especial. Corresponde a la Escala de Administración General el desempeño de funciones comunes al ejercicio de la actividad administrativa.'}},
  {n:27,q:'La Escala de Administración General de los funcionarios pertenecientes a las Corporaciones Locales está integrada:',o:{a:'Por dos subescalas.',b:'Por tres subescalas.',c:'Por cuatro subescalas.',d:'Por cinco subescalas.'},correct:'c',why:{'c':'La Escala de Administración General está integrada por las Subescalas técnica, administrativa, auxiliar y subalterna. La Subescala técnica realiza tareas de gestión y propuesta de carácter administrativo de nivel superior; la administrativa de trámite y colaboración; la auxiliar tareas mecanográficas; y la de subalternos funciones de vigilancia y custodia interior de oficinas.'}},
  {n:28,q:'La Escala de Administración Especial de los funcionarios pertenecientes a las Corporaciones Locales está integrada:',o:{a:'Por dos subescalas.',b:'Por tres subescalas.',c:'Por cuatro subescalas.',d:'Por cinco subescalas.'},correct:'a',why:{'a':'La Escala de Administración Especial consta de dos Subescalas: la Técnica y la de Servicios Especiales, según la actual organización. Tienen tal consideración aquellos funcionarios a quienes se atribuye el desempeño de funciones que constituyen el objeto peculiar de una carrera, profesión, arte u oficio.'}},
  {n:29,q:'La Policía Local, ¿en qué escala y subescala del personal de las Corporaciones Locales se integra?',o:{a:'En la Escala de Administración General, Subescala técnica.',b:'En la Escala de Administración General, Subescala auxiliar.',c:'En la Escala de Administración Especial, Subescala técnica.',d:'En la Escala de Administración Especial, Subescala servicios especiales.'},correct:'d',why:{'d':'La Policía Local se integra dentro de la Subescala de Servicios Especiales. En la Subescala de servicios especiales se establecen las siguientes clases: Policía local y sus Auxiliares, Servicio de Extinción de Incendios, Plazas de cometidos especiales y Personal de oficios.'}},
  {n:30,q:'El personal de las Bandas de Música se integra dentro de la Escala de Administración Especial:',o:{a:'En la Subescala técnica.',b:'En la Subescala de servicios especiales.',c:'En la Subescala de cometidos especiales.',d:'En la Subescala de Personal de Oficios.'},correct:'b',why:{'b':'En la Subescala de servicios especiales se incluye, de forma específica, al personal de las Bandas de Música, dentro de la clase de plazas de cometidos especiales, subdividiéndose en categorías según el nivel de titulación exigido para el ingreso.'}},
  {n:31,q:'Todos los puestos de trabajo reservados a funcionarios, personal laboral y eventual constituye:',o:{a:'La organización del Ayuntamiento.',b:'La clasificación de los puestos de trabajo.',c:'La oferta de empleo público.',d:'La plantilla.'},correct:'d',why:{'d':'La plantilla, que será aprobada anualmente por el Pleno de la Corporación local a través del Presupuesto, es el documento que comprende todos los puestos de trabajo reservados a funcionarios, personal laboral y eventual. Deberá responder a los principios de racionalidad, economía y eficiencia.'}},
  {n:32,q:'La denominación de los puestos de trabajo y los grupos de clasificación profesional a que estén en su caso adscritos se deberán incluir:',o:{a:'En la relación de puestos de trabajo.',b:'La clasificación de los puestos de trabajo.',c:'En la oferta de empleo público.',d:'En la plantilla.'},correct:'a',why:{'a':'Conforme al art. 74 del EBEP, las Administraciones Públicas estructurarán su organización a través de relaciones de puestos de trabajo u otros instrumentos organizativos similares que comprenderán, al menos, la denominación de los puestos, los grupos de clasificación profesional, los cuerpos o escalas, los sistemas de provisión y las retribuciones complementarias.'}},
  {n:33,q:'¿Qué datos deberán inscribirse en el Registro de Personal que se contempla en el EBEP?',o:{a:'Los datos que no sean objeto de protección de acuerdo con la Ley Orgánica de Protección de Datos Personales.',b:'Los datos recogidos de fuentes accesibles al público.',c:'Los datos cuya cesión esté autorizada por una Ley.',d:'El EBEP no enumera los datos que deberán incluirse en el Registro de Personal.'},correct:'d',why:{'d':'El Registro de Personal se regula en el art. 71 del EBEP, que difiere a la celebración de un Convenio de Conferencia Sectorial el establecimiento de los contenidos mínimos comunes en los datos que haya que incorporar al Registro de Personal. El Estatuto Básico no enumera directamente los datos.'}},
  {n:34,q:'La ejecución de la oferta de empleo público deberá desarrollarse dentro de un plazo improrrogable de:',o:{a:'Un año.',b:'Dos años.',c:'Tres años.',d:'Cuatro años.'},correct:'c',why:{'c':'Los procesos de selección habrán de ser obligatoriamente convocados en el plazo que la oferta establezca, y cuya duración —hasta su finalización— no podrá exceder de tres años (art. 70.1 EBEP). La convocatoria de cada prueba deberá incluir todas las plazas fijadas en la oferta y hasta un 10% adicional.'}},
  {n:35,q:'La oferta de empleo público se aprobará por los órganos de Gobierno de las Administraciones Públicas:',o:{a:'Cuando se hubieran producido vacantes.',b:'En los casos de creación de nuevos servicios.',c:'Anualmente.',d:'Como mínimo una vez cada tres años.'},correct:'c',why:{'c':'La oferta de empleo público tiene carácter anual. El art. 70.2 del EBEP dispone que «la Oferta de empleo público o instrumento similar, que se aprobará anualmente por los órganos de Gobierno de las Administraciones Públicas, deberá ser publicada en el Diario oficial correspondiente».'}},
  {n:36,q:'La aprobación y publicación anual de la oferta de empleo público en el ámbito de las Corporaciones Locales tendrá lugar:',o:{a:'Dentro del plazo de un mes desde la aprobación del presupuesto.',b:'Dentro del plazo de tres meses desde la aprobación del presupuesto.',c:'En el primer trimestre del año.',d:'Inmediatamente después de aprobado el presupuesto.'},correct:'a',why:{'a':'En el ámbito local, las ofertas deberán publicarse dentro del mes siguiente al de la aprobación de sus Presupuestos. En el sector estatal, la publicación de la oferta se efectúa dentro del primer trimestre de cada año natural.'}},
  {n:37,q:'La progresión de grado, categoría, u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo se denomina:',o:{a:'Carrera vertical.',b:'Promoción interna.',c:'Ascenso.',d:'Carrera horizontal.'},correct:'d',why:{'d':'La carrera horizontal consiste en la progresión de grado, categoría, escalón u otros conceptos análogos sin necesidad de cambiar de puesto de trabajo (art. 16.3.a EBEP). La carrera vertical consiste en el ascenso en la estructura de puestos de trabajo; la promoción interna en el ascenso a cuerpos de subgrupo o grupo superior.'}},
  {n:38,q:'A fin de valorar el rendimiento en el trabajo, el EBEP crea un nuevo instrumento denominado:',o:{a:'Estimación del rendimiento.',b:'Evaluación del desempeño.',c:'Evaluación de la aptitud.',d:'Metodología del rendimiento.'},correct:'b',why:{'b':'El art. 20.1 del EBEP define la evaluación del desempeño como «el procedimiento mediante el cual se mide y valora la conducta profesional y el rendimiento o el logro de resultados». El EBEP instaura este instrumento novedoso a fin de valorar el rendimiento profesional de los funcionarios.'}},
  {n:39,q:'La evaluación del desempeño no podrá tener efectos:',o:{a:'En la carrera profesional horizontal.',b:'En la formación y en la provisión de puestos de trabajo.',c:'En la percepción de las retribuciones complementarias.',d:'En la percepción de las retribuciones básicas.'},correct:'d',why:{'d':'El EBEP no hace ninguna referencia a los efectos positivos o negativos de la evaluación del desempeño en las retribuciones básicas (sueldo, trienios o pagas extraordinarias). Sí tiene efectos en la carrera horizontal, formación, provisión de puestos y retribuciones complementarias (arts. 17, 20.3 y 24 EBEP).'}},
  {n:40,q:'La continuidad en el puesto de trabajo, ¿podrá quedar vinculada a la evaluación del desempeño?',o:{a:'Sí, en el caso de puestos de trabajo obtenidos por concurso.',b:'Sí, en el caso de puestos de trabajo obtenidos por oposición.',c:'Sí en el caso de puestos de trabajo obtenidos por concurso-oposición.',d:'No, en ningún caso.'},correct:'a',why:{'a':'El art. 20.4 del EBEP establece que «la continuidad en un puesto de trabajo obtenido por concurso quedará vinculada a la evaluación del desempeño de acuerdo con los sistemas de evaluación que cada Administración Pública determine, dándose audiencia al interesado, y por la correspondiente resolución motivada».'}},
  {n:41,q:'Las reglas básicas y los programas mínimos a que debe ajustarse el procedimiento de selección de los funcionarios de administración local se contienen en:',o:{a:'La Ley de Bases del Régimen Local.',b:'El Real Decreto 896/1991.',c:'El Estatuto Básico del Empleado Público.',d:'La Ley de medidas para la reforma de la función pública.'},correct:'b',why:{'b':'El Real Decreto 896/1991, de 7 de junio, establece las reglas básicas y los programas mínimos a que debe ajustarse el procedimiento de selección de los funcionarios de administración local, desarrollando directamente el art. 92.3 LBRL, con carácter básico pese a su forma reglamentaria.'}},
  {n:42,q:'¿Cuál se considera el procedimiento normal de provisión de puestos de trabajo del personal funcionario de carrera?',o:{a:'La libre designación sin convocatoria pública.',b:'La libre designación con convocatoria pública.',c:'El concurso.',d:'Ninguna respuesta es correcta.'},correct:'c',why:{'c':'El procedimiento normal de provisión de los puestos de trabajo es el concurso (art. 79 EBEP), trámite competitivo que ha de ser anunciado mediante convocatoria pública, en la que deben hacerse constar los puestos de trabajo a cubrir y, en su caso, los requisitos exigibles y los méritos para optar a los mismos.'}},
  {n:43,q:'¿Quién resolverá el concurso de provisión de puestos de trabajo?',o:{a:'Los órganos colegiados de carácter técnico.',b:'Los funcionarios de una escala superior a los puestos de trabajo que concursan.',c:'El personal directivo del órgano en cuestión.',d:'Todas las respuestas son correctas.'},correct:'a',why:{'a':'El concurso para la provisión de puestos de trabajo ha de ser resuelto, de acuerdo con el art. 79.1 del EBEP, por «órganos colegiados de carácter técnico», cuya composición «responderá al principio de profesionalidad y especialización de sus miembros y se adecuará al criterio de paridad entre mujer y hombre».'}},
  {n:44,q:'El funcionario que hubiese accedido a un puesto de trabajo obtenido por concurso, ¿podrá ser privado del mismo?',o:{a:'Sí, en caso de una evaluación desfavorable de su desempeño.',b:'Sí, en caso de que dicho puesto de trabajo se suprima.',c:'Sí, en caso de traslado por necesidades de servicio o funcionales, a unidades, departamentos u organismos públicos o entidades distintos a los de su destino.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'Quien obtenga un puesto de trabajo por concurso puede ser privado del mismo por evaluación desfavorable, por supresión del puesto, o por traslado motivado por necesidades de servicio o funcionales a unidades distintas a las de su destino (art. 79 EBEP), respetando sus retribuciones y condiciones esenciales de trabajo.'}},
  {n:45,q:'La provisión de puestos de trabajo del personal funcionario de carrera mediante libre designación:',o:{a:'Será aplicable en cualquier momento a cualquier puesto de trabajo.',b:'Nunca precisa de convocatoria pública.',c:'Se puede resolver mediante la apreciación discrecional del órgano competente.',d:'Se realizará de acuerdo con los criterios establecidos en el EBEP.'},correct:'c',why:{'c':'El procedimiento de libre designación se resuelve mediante «la apreciación discrecional por el órgano competente de la idoneidad de los candidatos» (art. 80 EBEP); se trata de una decisión libre ya que la existencia de confianza no puede objetivarse. Solo es aplicable a puestos previamente determinados en las relaciones de puestos de trabajo y precisa convocatoria pública.'}},
  {n:46,q:'¿Qué tipo de movilidad podrá producirse cuando se detecte la existencia de sectores prioritarios de la actividad pública con necesidades específicas de efectivos?',o:{a:'Movilidad forzosa.',b:'Movilidad voluntaria.',c:'Movilidad por razón de violencia de género.',d:'Movilidad forzada.'},correct:'b',why:{'b':'Los supuestos de movilidad voluntaria pueden producirse cuando se detecte la existencia de «sectores prioritarios de la actividad pública con necesidades específicas de efectivos» (art. 81.1 EBEP), habilitando a cada Administración para establecer «reglas para la ordenación de la movilidad voluntaria de los funcionarios».'}},
  {n:47,q:'La movilidad forzosa del personal funcionario de carrera:',o:{a:'Se producirá siempre como consecuencia de una sanción disciplinaria.',b:'Se podrá producir por necesidades de servicio o funcionales.',c:'Se producirá en cualquier caso sin derecho a indemnización.',d:'No exigirá motivación alguna por parte de la Administración.'},correct:'b',why:{'b':'El EBEP regula en su art. 81.2 la movilidad forzosa condicionándola a la existencia de «necesidades de servicio o funcionales». Deberá realizarse de forma motivada; cuando implique cambio de lugar de residencia se dará prioridad a la voluntariedad y darán derecho a la percepción de indemnizaciones reglamentarias.'}},
  {n:48,q:'El EBEP reconoce a las mujeres víctimas de violencia de género el traslado a otro puesto de trabajo:',o:{a:'Que tendrá carácter de traslado voluntario.',b:'Que tendrá carácter de traslado forzoso.',c:'Que no podrá tener derecho a indemnización.',d:'Que podrá realizarse en otro cuerpo o escala.'},correct:'b',why:{'b':'El EBEP en su art. 82 reconoce a las mujeres víctimas de violencia de género derecho «al traslado a otro puesto de trabajo propio de su cuerpo, escala o categoría profesional, de análogas características», bien en la propia localidad o en la que la víctima libremente elija, con los derechos inherentes a un supuesto de traslado forzoso (indemnización por gastos causados).'}},
  {n:49,q:'¿A qué principios constitucionales relacionados con el empleo público hace alusión el EBEP?',o:{a:'A los principios de igualdad, mérito y capacidad.',b:'A los principios de publicidad, igualdad, mérito y capacidad.',c:'A los principios de transparencia, imparcialidad y mérito.',d:'A los principios de publicidad, transparencia e imparcialidad.'},correct:'a',why:{'a':'Al tratar del acceso a la función pública, el EBEP enumera como principios constitucionales los de igualdad, mérito y capacidad. Además alude a otros como publicidad de las convocatorias, transparencia, imparcialidad y profesionalidad de los órganos de selección, independencia y discrecionalidad técnica, adecuación entre pruebas y funciones, y agilidad.'}},
  {n:50,q:'¿Se podrán establecer excepciones a los principios de mérito y capacidad en el acceso al empleo público?',o:{a:'No, en ningún caso.',b:'No, excepto lo que se refiere a la reserva de plazas para discapacitados.',c:'Sí, cuando así lo considere oportuno el órgano competente.',d:'Sí, ya que el mismo Estatuto establece una serie de excepciones a dichos principios.'},correct:'d',why:{'d':'El propio EBEP a lo largo de su articulado establece excepciones a los principios constitucionales de igualdad, mérito y capacidad, en función de otras finalidades como la igualdad de género, la protección de los discapacitados (art. 5.9 EBEP: reserva de plazas y ajustes razonables) y el fomento de las lenguas oficiales en las Comunidades autónomas bilingües.'}},
  {n:51,q:'¿Cuál de los siguientes no es un requisito para poder participar en los procesos selectivos?',o:{a:'Tener la nacionalidad española en cualquiera de los casos.',b:'Tener cumplidos dieciséis años.',c:'Poseer la titulación exigida.',d:'Acatar la Constitución.'},correct:'d',why:{'d':'El art. 55 EBEP prescribe los requisitos para participar en procesos selectivos: nacionalidad española, capacidad funcional, tener cumplidos 16 años y no exceder la edad máxima de jubilación forzosa, no haber sido separado por expediente disciplinario ni inhabilitado, y poseer la titulación exigida. El acatamiento de la Constitución no es requisito para participar, sino para adquirir definitivamente la condición de funcionario.'}},
  {n:52,q:'¿Podrá exigirse el cumplimiento de requisitos específicos para el acceso al empleo público?',o:{a:'No, en ningún caso.',b:'Sí, aunque no guarden relación objetiva con las funciones a desempeñar.',c:'Sí, aunque de forma concreta e individualizada.',d:'Ninguna respuesta es correcta.'},correct:'d',why:{'d':'El art. 56.3 EBEP establece que «podrá exigirse el cumplimiento de otros requisitos específicos que guarden relación objetiva y proporcionada con las tareas o funciones a desempeñar. En todo caso, habrán de establecerse de manera abstracta y general». Ninguna de las opciones a), b) o c) refleja correctamente estas condiciones.'}},
  {n:53,q:'Los nacionales de los Estados miembros de la Unión Europea ¿a qué puestos de trabajo podrán acceder en igualdad de condiciones que los españoles?',o:{a:'A cualquier puesto de trabajo incluidos aquellos que directa o indirectamente impliquen una participación en el ejercicio del poder público o en las funciones que tienen por objeto la salvaguardia de los intereses del Estado o de las Administraciones Públicas.',b:'A cualquier puesto de trabajo excepto aquéllos que impliquen ejercicio de autoridad.',c:'A cualquier puesto de trabajo como personal funcionario de carrera.',d:'A cualquier puesto de trabajo como personal laboral.'},correct:'d',why:{'d':'El art. 57.4 EBEP especifica que los nacionales de otros Estados de la UE, así como los que tengan residencia legal en España, podrán acceder a las Administraciones Públicas como personal laboral, en igualdad de condiciones que los españoles, conforme también a la LO 4/2000 de derechos y libertades de los extranjeros en España.'}},
  {n:54,q:'¿Podrá eximirse del requisito de la nacionalidad para el acceso a la condición de personal funcionario?',o:{a:'Sí, por Ley de las Cortes Generales.',b:'Sí, por Ley de las Asambleas de las Comunidades Autónomas.',c:'Sí, cuando además de la reserva legal existan razones de interés general.',d:'No, excepto cuando existan razones de interés general.'},correct:'c',why:{'c':'El art. 57.5 EBEP establece que «sólo por Ley de las Cortes Generales o de las Asambleas Legislativas de las Comunidades Autónomas podrá eximirse del requisito de la nacionalidad por razones de interés general para el acceso a la condición de personal funcionario». Se requieren ambas condiciones: reserva legal y razones de interés general.'}},
  {n:55,q:'Para poder participar en los procesos selectivos será necesario:',o:{a:'Tener cumplidos dieciocho años y no exceder la edad máxima de jubilación forzosa.',b:'Tener cumplidos dieciséis años y no exceder la edad máxima de jubilación forzosa.',c:'Tener cumplidos dieciséis años y no exceder de aquella edad en la que falten menos de diez años para la jubilación forzosa.',d:'Tener cumplidos dieciocho años y no exceder de aquella edad en la que falten menos de diez años para la jubilación forzosa.'},correct:'b',why:{'b':'El art. 56.1.c) del EBEP rebajó la edad mínima de dieciocho a dieciséis años, equiparándola con el derecho laboral. La edad máxima se equipara a la edad de jubilación forzosa. El TC declaró inconstitucional la condición de no exceder de aquella edad en que falten menos de diez años para la jubilación forzosa cuando se aplica de forma indiferenciada a todos los funcionarios (STC 37/2004).'}},
  {n:56,q:'Para poder participar en los procesos selectivos será necesario de acuerdo con lo dispuesto en el EBEP:',o:{a:'No padecer enfermedad impeditiva del desempeño de las correspondientes funciones.',b:'No padecer defecto físico impeditivo del desempeño de las correspondientes funciones.',c:'Poseer la capacidad funcional para desempeñar las funciones y tareas.',d:'No padecer incapacidad para desempeñar las funciones correspondientes.'},correct:'c',why:{'c':'El art. 56.1.b) del EBEP establece como requisito general «poseer la capacidad funcional para desempeñar las funciones y tareas». El EBEP cambió la terminología de la legislación anterior, optando por una nueva redacción en positivo. Para comprobar esa capacidad funcional el EBEP mantiene la posibilidad de que puedan exigirse reconocimientos médicos (art. 61.5 EBEP).'}},
  {n:57,q:'Para poder participar en los procesos selectivos será necesario:',o:{a:'Poseer la titulación exigida.',b:'Poseer la titulación exigida o estar en condiciones de obtenerla en la fecha en que termine el plazo de presentación de instancias.',c:'Poseer la titulación exigida o estar en condiciones de obtenerla antes de que se realicen las correspondientes pruebas.',d:'Poseer la titulación exigida antes de la fecha de publicación de la oferta de empleo público.'},correct:'a',why:{'a':'La nueva redacción del art. 56.1.e) del EBEP ha suprimido la segunda opción (estar en condiciones de obtener el título antes del fin del plazo de presentación de instancias), por los problemas que generaba. Por tanto habrá que entender como válido únicamente «poseer la titulación exigida».'}},
  {n:58,q:'No es condición para poder participar en los procesos selectivos:',o:{a:'No haber sido separado mediante expediente disciplinario del servicio de cualquiera de las Administraciones Públicas.',b:'No hallarse en inhabilitación absoluta para empleos o cargos públicos por resolución judicial, para el acceso al cuerpo o escala de funcionario.',c:'No hallarse en inhabilitación especial para empleos o cargos públicos por resolución judicial, para el acceso al cuerpo o escala de funcionario.',d:'Haber sido separado mediante expediente disciplinario del servicio de cualquiera de las Administraciones Públicas aunque posteriormente se hubiera sido rehabilitado.'},correct:'d',why:{'d':'El art. 56.1.d) EBEP exige no haber sido separado mediante expediente disciplinario ni hallarse en inhabilitación. Sin embargo, el art. 152.2 del TRRL contempla la posibilidad de rehabilitación cuando han sido separados del servicio por sanción disciplinaria, lo que significa que este requisito debe interpretarse sin perjuicio de la posibilidad de rehabilitación.'}},
  {n:59,q:'La exigencia del conocimiento de lenguas distintas del castellano en las Comunidades Autónomas con lenguas propias:',o:{a:'No se reconoce en el EBEP.',b:'Nunca se admitirá como requisito de capacidad.',c:'Nunca se admitirá como mérito.',d:'Podrá establecerse como requisito de capacidad y como mérito.'},correct:'d',why:{'d':'El art. 56.2 EBEP reproduce el deber de seleccionar empleados públicos capacitados para cubrir puestos en Comunidades con dos lenguas oficiales. El TC en la STC 46/1991 lo consideró «un requisito sine qua non» de capacidad. Adicionalmente, el conocimiento de la lengua cooficial puede establecerse como mérito en los procesos selectivos.'}},
  {n:60,q:'Los procesos de selección cuidarán especialmente:',o:{a:'La conexión entre el tipo de pruebas a superar y la adecuación al desempeño de las tareas de los puestos de trabajo convocados.',b:'Que el número mínimo de temas en que deberán desarrollarse los contenidos vaya en correlación con el grupo al que se pretende acceder.',c:'Que los ejercicios obligatorios no tengan carácter de eliminatorios.',d:'Que las pruebas de capacidad no determinen por sí mismas el resultado del proceso selectivo.'},correct:'a',why:{'a':'El art. 60.2 EBEP recoge como principio que «los procedimientos de selección cuidarán especialmente la conexión entre el tipo de pruebas a superar y la adecuación al desempeño de las tareas de los puestos de trabajo convocados». Este principio de adecuación era ya una novedad de la LMRFP y se ha reiterado en todas las normas posteriores.'}},
  {n:61,q:'¿Cuál es el sistema de selección consistente en superar las pruebas de capacidad teóricas y prácticas exigidas en la convocatoria pública para determinar la aptitud de los aspirantes y fijar el orden de prelación de los mismos en la selección?',o:{a:'La oposición.',b:'El concurso.',c:'El concurso-oposición.',d:'Ninguna respuesta es correcta.'},correct:'a',why:{'a':'La oposición consiste en superar las pruebas de capacidad teóricas y prácticas exigidas en la convocatoria pública para determinar la aptitud de los aspirantes y fijar el orden de prelación de los mismos. Según el art. 4.c) del RD 896/1991 las pruebas tendrán carácter eliminatorio y en los ejercicios escritos deberá garantizarse, siempre que sea posible, el anonimato de los aspirantes.'}},
  {n:62,q:'¿Qué sistema tiene en cuenta tanto la valoración de la capacidad del candidato mediante pruebas como los méritos que este candidato aporta?',o:{a:'La oposición.',b:'El concurso.',c:'El concurso-oposición.',d:'Ninguna respuesta es correcta.'},correct:'c',why:{'c':'El concurso-oposición es una combinación tanto de la oposición como del concurso. El EBEP previene que en él se deberán incluir, en todo caso, una o varias pruebas para determinar la capacidad de los aspirantes y establecer el orden de prelación, además de la fase de valoración de méritos.'}},
  {n:63,q:'El sistema selectivo general para el caso de los funcionarios será:',o:{a:'La oposición.',b:'El concurso-oposición.',c:'La oposición o el concurso-oposición.',d:'La oposición o el concurso.'},correct:'c',why:{'c':'El art. 61.6 EBEP especifica que «los sistemas selectivos de funcionarios de carrera serán los de oposición y concurso-oposición que deberán incluir, en todo caso, una o varias pruebas para determinar la capacidad de los aspirantes y establecer el orden de prelación. Solo en virtud de Ley podrá aplicarse, con carácter excepcional, el sistema de concurso».'}},
  {n:64,q:'De acuerdo con lo previsto en el EBEP, ¿cuál no debe de ser el sistema de selección ordinario?',o:{a:'La oposición.',b:'El concurso.',c:'El concurso-oposición.',d:'Ninguna respuesta es correcta.'},correct:'b',why:{'b':'El EBEP predetermina en su art. 61.6 que «el concurso de méritos solo podrá utilizarse con carácter excepcional y en virtud de ley», elevando a categoría de norma básica la excepcionalidad de este sistema. Sin embargo, se mantiene la paradoja de mantenerlo como sistema normal para la selección de personal laboral fijo (art. 61.7 EBEP).'}},
  {n:65,q:'La valoración de méritos de los aspirantes en los procesos selectivos que incluyan pruebas de capacidad, ¿podrán determinar por sí mismas el resultado del proceso selectivo?',o:{a:'Sí, en el caso en que así se establezca en las bases de la convocatoria.',b:'Sí, en el caso en que así lo exija la naturaleza de las plazas o de las funciones a desempeñar.',c:'No, excepto que se trate de procesos para la selección de personal funcionario de carrera.',d:'No.'},correct:'d',why:{'d':'El art. 60.3 del EBEP establece que «los procesos selectivos que incluyan, además de las preceptivas pruebas de capacidad, la valoración de méritos de los aspirantes solo podrán otorgar a dicha valoración una puntuación proporcionada que no determinará, en ningún caso, por sí misma el resultado del proceso selectivo».'}},
  {n:66,q:'La movilidad interadministrativa de los funcionarios públicos:',o:{a:'No se recoge en el EBEP.',b:'Se regula en el EBEP como un deber de las Administraciones públicas del que se derivan consecuencias de su incumplimiento.',c:'Se recoge como derecho a la movilidad de los funcionarios pero dentro de la Administración pública a la que pertenecen.',d:'Ninguna respuesta es correcta.'},correct:'d',why:{'d':'El EBEP sigue una línea voluntarista y dice que las diferentes Administraciones territoriales «establecerán medidas de movilidad interadministrativa» (art. 84.1), pero no contempla ninguna consecuencia ante el incumplimiento de este deber. Tampoco se configura como un derecho de los funcionarios. Ninguna de las opciones a, b o c describe correctamente la regulación.'}},
  {n:67,q:'El EBEP en lo que se refiere a la movilidad interadministrativa:',o:{a:'Establece el Acuerdo-Marco entre las Administraciones públicas como vía preferente para instrumentar este derecho.',b:'Contiene el sistema de homologación de los grupos profesionales para facilitar y garantizar las posibilidades de movilidad.',c:'Prevé que en caso de movilidad interadministrativa los funcionarios de carrera que obtengan destino en otra Administración Pública quedarán respecto de su Administración de origen en la situación administrativa de servicio en otras Administraciones Públicas.',d:'Ninguna respuesta es correcta.'},correct:'c',why:{'c':'El art. 84.3 EBEP establece que los funcionarios de carrera que obtengan destino en otra Administración Pública «quedarán respecto de su Administración de origen en la situación administrativa de servicio en otras Administraciones Públicas». En caso de cese o supresión del puesto, permanecerán en la Administración de destino, que deberá asignarles un puesto conforme a los sistemas de carrera y provisión vigentes.'}},
  {n:68,q:'El nombramiento definitivo como funcionario de carrera:',o:{a:'Se realiza tras el acto de acatamiento de la Constitución.',b:'Se realizará siempre de modo inmediato a la presentación de los documentos requeridos.',c:'Se realizará tras la toma de posesión.',d:'Se realizará una vez superado con éxito el período de prácticas en caso de que este período estuviera previsto.'},correct:'d',why:{'d':'Si la convocatoria hubiere previsto la realización de un período de prácticas o curso selectivo posterior a las pruebas, los aspirantes son nombrados funcionarios en prácticas, y solo superado con éxito uno u otro se les expide el nombramiento definitivo como funcionarios de carrera. En otro caso, el nombramiento definitivo sigue de modo inmediato a la presentación de los documentos.'}},
  {n:69,q:'El acto de acatamiento de la Constitución:',o:{a:'Se realiza con posterioridad al nombramiento.',b:'Es un requisito formal de obligatorio cumplimiento cuya inobservancia determina la caducidad automática del nombramiento.',c:'Su incumplimiento se equipara a la renuncia tácita por parte del nombrado.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'Tras el nombramiento debe realizarse el «acto de acatamiento de la Constitución y, en su caso, del Estatuto de Autonomía correspondiente y del resto del Ordenamiento Jurídico» (art. 62.1.c) EBEP). Es un requisito formal de obligatorio cumplimiento que se realiza con posterioridad al nombramiento. La falta de toma de posesión en el plazo establecido se considera renuncia tácita a los derechos adquiridos.'}},
  {n:70,q:'¿Cuál es el último acto preceptivo para la adquisición de la condición de funcionario?',o:{a:'El nombramiento definitivo.',b:'El acatamiento de la Constitución.',c:'La toma de posesión.',d:'La aportación de la documentación requerida tras la superación de las pruebas selectivas.'},correct:'c',why:{'c':'La toma de posesión, aunque se suele realizar en el mismo acto que el acatamiento de la Constitución, se considera el último requisito formal de obligatorio cumplimiento para que se adquiera legalmente la condición de funcionario y quede formalizada legalmente la relación funcionarial. Determina la adquisición de los derechos y deberes funcionariales inherentes a la situación en activo.'}},
  {n:71,q:'¿A cuál de las siguientes causas de pérdida de la condición de funcionario de carrera no alude el EBEP?',o:{a:'A la renuncia.',b:'Al fallecimiento.',c:'A la pérdida de la nacionalidad.',d:'A la jubilación total de funcionario.'},correct:'b',why:{'b':'El EBEP enumera como causas de pérdida de la condición de funcionario de carrera (arts. 63 a 68): la renuncia, la pérdida de la nacionalidad, la jubilación total, la sanción disciplinaria de separación del servicio firme, y la pena principal o accesoria de inhabilitación absoluta o especial firme. Sin embargo, no menciona el fallecimiento del funcionario.'}},
  {n:72,q:'La renuncia como causa de la pérdida de la condición de funcionario es un acto:',o:{a:'Que inhabilita para ingresar de nuevo en la Administración pública a través de los procedimientos de selección.',b:'Mediante el cual el funcionario puede poner fin a la relación de servicio con la Administración en cualquier momento de su vida laboral.',c:'Cuya aceptación por la Administración tiene el carácter de reglado y debido.',d:'Que puede estar condicionado a las necesidades de servicio de la Administración.'},correct:'c',why:{'c':'La renuncia debe ser formalizada mediante escrito debiendo ser aceptada de forma expresa por la Administración, aceptación que es estrictamente reglada y debida salvo en los casos en que legalmente no proceda. El EBEP no impone límites al derecho de renuncia como pudieran ser condicionarla a las necesidades del servicio.'}},
  {n:73,q:'La pérdida de la nacionalidad española:',o:{a:'Siempre causa de la pérdida de la condición de funcionario.',b:'Nunca causa de la pérdida de la condición de funcionario.',c:'No causa la pérdida de la condición de funcionario si la nacionalidad pérdida es sustituida por otra que también habilite para el ingreso en la función pública.',d:'Siempre causa la pérdida de la condición de funcionario aunque se puede producir la rehabilitación si se recupera de nuevo la nacionalidad.'},correct:'c',why:{'c':'El art. 65 del EBEP determina que «la pérdida de la nacionalidad española o la de cualquier otro Estado miembro de la Unión Europea... que haya sido tenida en cuenta para el nombramiento, determinará la pérdida de la condición de funcionario salvo que simultáneamente se adquiera la nacionalidad de alguno de dichos Estados».'}},
  {n:74,q:'¿Qué tipo de inhabilitación causa la pérdida de la condición de funcionario en todos los empleos o cargos que el funcionario viniera desarrollando?',o:{a:'La inhabilitación absoluta.',b:'La inhabilitación especial.',c:'La inhabilitación absoluta o especial.',d:'Cualquier clase de inhabilitación.'},correct:'a',why:{'a':'La pena de inhabilitación absoluta extingue la condición de funcionario respecto a todos los empleos o cargos que el condenado viniera desarrollando, mientras que la pena de inhabilitación especial extingue la condición de funcionario solamente respecto de aquellos empleos o cargos especificados en la sentencia (art. 63.e EBEP).'}},
  {n:75,q:'¿Cuál la forma normal y más habitual de pérdida de la condición de funcionario?',o:{a:'La renuncia.',b:'La jubilación.',c:'La inhabilitación.',d:'La pérdida de la nacionalidad.'},correct:'b',why:{'b':'La forma normal de extinción de la condición de funcionario es la jubilación, que admite las siguientes modalidades: jubilación voluntaria a solicitud del interesado, jubilación forzosa al cumplir la edad reglamentaria, jubilación por incapacidad permanente, y jubilación parcial (art. 67 EBEP).'}},
  {n:76,q:'La rehabilitación de la condición de funcionario:',o:{a:'No es posible ya que la pérdida de la condición de funcionario es siempre irreversible.',b:'Nunca se podrá conceder en caso de haber sido condenado en sentencia firme a la pena principal o accesoria de inhabilitación.',c:'Se podrá conceder, con carácter excepcional, para quien hubiera sido condenado a la pena principal o accesoria de inhabilitación, atendiendo a las circunstancias y entidad del delito cometido.',d:'Solamente se podrá conceder, a petición del interesado, como consecuencia de la recuperación de la nacionalidad española.'},correct:'c',why:{'c':'El art. 68.2 del EBEP contempla un supuesto de derecho de gracia: los órganos de gobierno de las Administraciones públicas podrán conceder, con carácter excepcional, la rehabilitación a quien hubiera perdido la condición de funcionario por haber sido condenado a la pena de inhabilitación, atendiendo a las circunstancias y entidad del delito cometido. Si transcurre el plazo sin resolución expresa, se entiende desestimada.'}},
  {n:77,q:'El ascenso desde cuerpos o escalas de un grupo de titulación a otros del inmediato superior se denomina:',o:{a:'Movilidad.',b:'Promoción interna.',c:'Progresión en el desempeño.',d:'Progresión en la movilidad.'},correct:'b',why:{'b':'La definición general de promoción interna, recogida en el art. 22.1 de la Ley de Medidas, la considera «el ascenso desde cuerpos o escalas de un grupo de titulación a otros del inmediato superior». El EBEP regula dos modalidades: la promoción interna vertical (ascenso a subgrupo o grupo superior) y la horizontal (acceso a cuerpos o escalas del mismo subgrupo).'}},
  {n:78,q:'Las bases de las convocatorias del personal al servicio de la Administración Local no se publicarán:',o:{a:'En el Boletín Oficial del Estado.',b:'En el Boletín Oficial del Provincia.',c:'En el Boletín Oficial de la Provincia y en el Boletín Oficial de la Comunidad Autónomas.',d:'En el Boletín Oficial de la provincia, en el Boletín Oficial de la Comunidad Autónoma y, en su caso, en otros diarios oficiales o en el periódico oficial de la Corporación interesada.'},correct:'a',why:{'a':'El art. 6.1 del RD 896/1991 dispone que las bases de las pruebas selectivas se publicarán en el BOE de la provincia, el BOE de la Comunidad Autónoma y, en su caso, en otros diarios oficiales o en el periódico oficial de la Corporación. En el BOE no se publican las bases sino una sucinta relación del número de plazas, denominación y boletín oficial en que deban publicarse.'}},
  {n:79,q:'Las solicitudes para participar en el procedimiento de selección en las convocatorias del personal al servicio de la Administración local ¿en qué momento deberán formularse?',o:{a:'Dentro del plazo de veinte días naturales a partir del día siguiente de la publicación de la convocatoria.',b:'Dentro del plazo de veinte días hábiles a partir del día siguiente de la publicación de la convocatoria.',c:'Dentro del plazo de diez veinticinco días naturales a partir del día siguiente de la publicación de la convocatoria.',d:'Cuando se estime en la oferta de empleo público.'},correct:'a',why:{'a':'Las solicitudes para participar en el procedimiento de selección en las convocatorias del personal al servicio de la Administración local deberán formularse en modelo oficial dentro del plazo de veinte días naturales a partir del día siguiente de la publicación de la convocatoria, así lo dispone el art. 17 del Real Decreto 896/1991.'}},
  {n:80,q:'Las situaciones administrativas de los funcionarios de la Administración Local se regulan:',o:{a:'En el Texto Refundido de Régimen Local.',b:'En el Estatuto Básico del Empleado Público.',c:'En el Estatuto Básico del Empleado Público y en las leyes y demás normativa de función pública de las Comunidades Autónomas.',d:'En los Reglamento de Situaciones Administrativas de las Corporaciones Locales.'},correct:'c',why:{'c':'Las situaciones administrativas de los funcionarios de la Administración Local se regulan por la normativa básica estatal y por la legislación de la función pública de las respectivas Comunidades Autónomas y supletoriamente por la legislación de los funcionarios de la Administración del Estado. Los arts. 85 a 90 del EBEP distinguen: servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones.'}},
  {n:81,q:'El EBEP clasifica los derechos de los empleados públicos como:',o:{a:'Derechos individuales y derechos individuales ejercidos colectivamente.',b:'Derechos funcionales y derechos asistenciales.',c:'Derechos políticos y derechos asistenciales.',d:'Derechos económicos y derechos funcionales.'},correct:'a',why:{'a':'El EBEP distingue entre derechos de carácter individual (arts. 14) y derechos individuales ejercidos colectivamente (art. 15). Los derechos individuales incluyen derechos funcionales (inamovilidad, carrera, jornada, permisos) y económicos (retribuciones). Los ejercidos colectivamente comprenden la negociación colectiva, representación, participación institucional y derecho de reunión.'}},
  {n:82,q:'El derecho a la inamovilidad en la condición de funcionario de carrera:',o:{a:'Se debe entender como la permanencia indefinida en la condición de funcionario.',b:'Garantiza la permanencia en un determinado puesto de trabajo durante toda la vida laboral.',c:'Protege al funcionario del traslado a otro destino.',d:'Impide que el funcionario ser removido de su puesto de trabajo cuando sea evaluado negativamente por su desempeño.'},correct:'a',why:{'a':'El art. 14.a) del EBEP garantiza únicamente la permanencia indefinida en la condición de funcionario, pero no significa el derecho a la permanencia en un determinado puesto de trabajo y no protege al funcionario del traslado a otro destino. El funcionario también podrá ser desposeído de su puesto cuando sea evaluado negativamente por su desempeño.'}},
  {n:83,q:'La permanencia indefinida en la condición de empleado público es un derecho del que disfrutan:',o:{a:'En exclusiva los funcionarios de carrera.',b:'Los contratados laborales por tiempo indefinido.',c:'Los funcionarios interinos.',d:'Los funcionarios eventuales.'},correct:'b',why:{'b':'La permanencia indefinida en condición de empleado público no es exclusiva de los funcionarios ya que los contratados laborales por tiempo indefinido disfrutan de una situación prácticamente asimilable a la de los funcionarios. El EBEP excluye de este derecho tanto a los funcionarios interinos y eventuales como a los contratados laborales cuya relación no es por tiempo indefinido.'}},
  {n:84,q:'De acuerdo con lo previsto en el artículo 14.b del EBEP los empleados públicos tienen derecho al desempeño efectivo de:',o:{a:'Un puesto de trabajo concreto.',b:'Un puesto de trabajo específico.',c:'Las funciones o tareas propias de su condición profesional.',d:'Las prerrogativas del cargo que ostentan.'},correct:'c',why:{'c':'El art. 14.b del EBEP hace referencia al derecho de los empleados públicos «al desempeño efectivo de las funciones o tareas propias de su condición profesional», añadiendo «de acuerdo con la progresión alcanzada en su carrera profesional». Es un derecho vinculado al puesto que en cada momento desempeñe el empleado público.'}},
  {n:85,q:'El derecho de los empleados públicos a la progresión en la carrera profesional y promoción interna se realizará según los principios constitucionales de:',o:{a:'Igualdad, mérito y publicidad.',b:'Igualdad, mérito y capacidad.',c:'Transparencia, mérito e imparcialidad.',d:'Objetividad, mérito y capacidad.'},correct:'b',why:{'b':'El art. 14.c) EBEP establece el derecho «a la progresión en la carrera profesional y promoción interna según principios constitucionales de igualdad, mérito y capacidad mediante la implantación de sistemas objetivos y transparentes de evaluación». Las Administraciones Públicas promoverán la actualización y perfeccionamiento de la cualificación profesional de sus funcionarios.'}},
  {n:86,q:'El derecho a la carrera profesional y promoción personal:',o:{a:'No se reconoce en el EBEP al personal laboral sino solamente a los funcionarios de carrera.',b:'Se reconoce al personal laboral a través de lo dispuesto en el Estatuto de los Trabajadores.',c:'Se reconoce al personal laboral a través de lo dispuesto en los Convenios Colectivos.',d:'Se reconoce al personal laboral a través de lo dispuesto en el Estatuto de los Trabajadores y en los Convenios Colectivos.'},correct:'d',why:{'d':'El art. 19 del EBEP reconoce el derecho del personal laboral a la carrera profesional y promoción personal, que se hará efectiva a través de los procedimientos previstos en el Estatuto de los Trabajadores o en los Convenios Colectivos. Las relaciones de derechos establecidas en los arts. 14 y 15 del EBEP son en principio comunes al personal funcionario y laboral.'}},
  {n:87,q:'El derecho a la progresión en la carrera profesional regulado en el artículo 14.c) del EBEP:',o:{a:'Deberá ser desarrollado por las leyes de función pública que se dicten en desarrollo del EBEP.',b:'Se puede ejercer simultáneamente en las modalidades de carrera horizontal y vertical cuando la Administración correspondiente las haya implantado en un mismo ámbito.',c:'No excluye el derecho a la promoción interna.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'El EBEP encomienda a las Leyes de desarrollo la regulación del modelo de carrera aplicable en cada ámbito. Los funcionarios pueden progresar simultáneamente en las modalidades de carrera horizontal y vertical cuando la Administración las haya implantado en un mismo ámbito (art. 16.4 EBEP). Estas modalidades tampoco excluyen la promoción interna (Disp. Final 3.ª.2 EBEP).'}},
  {n:88,q:'El ascenso en la estructura de puestos de trabajo producido a través de los procedimientos de concurso y libre designación con convocatoria pública se denomina:',o:{a:'Carrera horizontal.',b:'Carrera vertical.',c:'Promoción interna vertical.',d:'Promoción interna horizontal.'},correct:'b',why:{'b':'La carrera vertical del funcionario consiste en el ascenso en la estructura de puestos de trabajo (art. 16.3.b) EBEP), lo que se producirá —como regla— a través de dos procedimientos: concurso y libre designación con convocatoria pública. La carrera profesional de los funcionarios se iniciará en el grado, nivel o categoría correspondiente a la plaza inicialmente asignada (Disp. Adicional 10.ª EBEP).'}},
  {n:89,q:'La denominada carrera horizontal consiste:',o:{a:'En la progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo.',b:'En la progresión de grado, categoría, escalón u otros conceptos análogos, necesitando como requisito cambiar de puesto de trabajo.',c:'En el ascenso en la estructura de los puestos de trabajo a través de concurso.',d:'Ninguna respuesta es correcta.'},correct:'a',why:{'a':'La carrera horizontal consiste en la progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo y de conformidad con lo establecido en los arts. 17.b) y 20.3 EBEP (art. 16.3.a EBEP). Permite que el funcionario no deba abandonar la tarea que desarrolla para ocuparse de nuevos ámbitos.'}},
  {n:90,q:'¿Qué sistema permite al funcionario dar un salto cualitativo en su carrera profesional, pasando de un grupo o subgrupo y/o cuerpo o escala a otro distinto?',o:{a:'La carrera horizontal.',b:'La carrera vertical.',c:'La promoción interna.',d:'La movilidad interadministrativa.'},correct:'c',why:{'c':'La promoción interna es un sistema que permite al funcionario dar un salto cualitativo en su carrera profesional, pasando de un grupo o subgrupo y/o cuerpo o escala a otro. La Ley obliga a las Administraciones públicas a adoptar medidas que incentiven la participación en procesos de promoción interna (art. 18.4 EBEP). En el ámbito local se permite una reserva de hasta el 50% de las plazas convocadas para promoción interna (art. 134.1 TRRL).'}},
  {n:91,q:'¿Cuántas modalidades de promoción interna contempla el EBEP?',o:{a:'Una única modalidad.',b:'Dos modalidades.',c:'Tres modalidades.',d:'Cuatro modalidades.'},correct:'b',why:{'b':'El EBEP contempla dos modalidades de promoción interna: la promoción interna vertical (ascenso desde un cuerpo o escala de un Subgrupo, o Grupo, a otro superior —art. 16.3.c) EBEP—) y la promoción interna horizontal (acceso a cuerpos o escalas del mismo Subgrupo profesional —art. 16.3.d) EBEP—).'}},
  {n:92,q:'¿Cuál de las siguientes proposiciones respecto de la promoción interna no es cierta?',o:{a:'La promoción interna de los funcionarios de carrera se realizará mediante procesos selectivos que garanticen el cumplimiento de los principios constitucionales de igualdad, mérito y capacidad.',b:'Los funcionarios deberán tener una antigüedad de, al menos, dos años de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo.',c:'El personal laboral también tiene derecho a la promoción profesional.',d:'El EBEP determina los cuerpos y escalas a los que podrán acceder los funcionarios de carrera pertenecientes a otros de su mismo Subgrupo.'},correct:'d',why:{'d':'Las Leyes de Función Pública que se dicten en desarrollo del EBEP articularán los sistemas para realizar la promoción interna, así como también podrán determinar los cuerpos y escalas a los que podrán acceder los funcionarios de carrera pertenecientes a otros de su mismo Subgrupo (art. 18.3 EBEP). No es el EBEP directamente quien los determina.'}},
  {n:93,q:'¿Cuál de las siguientes proposiciones sobre la movilidad voluntaria interadministrativa no es cierta?',o:{a:'La movilidad voluntaria interadministrativa se configura como un derecho de los empleados públicos.',b:'Los funcionarios de carrera que obtengan destino en otra Administración Pública a través de los procedimientos de movilidad quedarán respecto de su Administración de origen en la situación administrativa de servicio en otras Administraciones Públicas.',c:'Los funcionarios de carrera de la Administración local que obtengan destino a través de la movilidad voluntaria interadministrativa se encontrarán en la situación de servicio en Comunidades Autónomas.',d:'En los supuestos de cese o supresión del puesto de trabajo obtenido mediante movilidad voluntaria interadministrativa, los funcionarios permanecerán en la Administración de destino, que deberá asignarles un puesto de trabajo conforme a los sistemas de carrera y provisión vigentes en dicha Administración.'},correct:'a',why:{'a':'La movilidad administrativa voluntaria no se configura como un derecho de los funcionarios, ya que su finalidad es «lograr un mejor aprovechamiento de los recursos humanos, que garantice la eficacia del servicio que se preste a los ciudadanos» (art. 84.1 EBEP). Sirve primariamente a la racionalidad en la gestión pública, no a la carrera administrativa.'}},
  {n:94,q:'El sistema retributivo común a todos los funcionarios públicos distingue los siguientes conceptos retributivos:',o:{a:'Retribuciones básicas y retribuciones complementarias.',b:'Retribuciones básicas, retribuciones complementarias y otros conceptos retributivos.',c:'Sueldo, trienios y pagas extraordinarias.',d:'Sueldo, trienios y complementos.'},correct:'b',why:{'b':'El sistema retributivo común a todos los funcionarios públicos, de conformidad con los arts. 23 y 24 de la LMRFP y mantenido por el EBEP, distingue los siguientes conceptos retributivos: retribuciones básicas, retribuciones complementarias y otros conceptos retributivos. El EBEP sigue manteniendo dicha estructura por considerar que compensan diferentes aspectos de la relación de servicio.'}},
  {n:95,q:'Son retribuciones básicas que, de acuerdo con lo establecido en el EBEP, se fijan en la Ley de Presupuestos Generales del Estado:',o:{a:'El sueldo y los trienios.',b:'El sueldo, los trienios y las pagas extraordinarias.',c:'El sueldo, los trienios y los complementos.',d:'El sueldo y las pagas extraordinarias.'},correct:'a',why:{'a':'De acuerdo con el art. 23 del EBEP las retribuciones básicas, que se fijan en la Ley de Presupuestos Generales del Estado, estarán integradas única y exclusivamente por el sueldo y los trienios. Las pagas extraordinarias, con la nueva estructura retributiva del EBEP, aparecen como un concepto retributivo autónomo e independiente.'}},
  {n:96,q:'¿Cómo se denomina la cantidad retributiva asignada a los funcionarios en función del Grupo o Subgrupo de clasificación profesional al que pertenezcan?',o:{a:'Retribución básica.',b:'Sueldo.',c:'Trienio.',d:'Complemento.'},correct:'b',why:{'b':'El art. 23.1.a) EBEP define el sueldo como el asignado a cada Subgrupo o Grupo de clasificación profesional, en el supuesto de que este no tenga Subgrupo. El sueldo se integra por una cantidad fija a cada grupo de titulación, que a su vez corresponde con la titulación exigida para el ingreso. Su cuantía exacta la determina para cada ejercicio la Ley de Presupuestos Generales del Estado.'}},
  {n:97,q:'Los funcionarios en prácticas percibirán como mínimo:',o:{a:'El sueldo de los funcionarios del Subgrupo C2.',b:'El sueldo de los funcionarios del Subgrupo C1.',c:'El sueldo del los funcionarios del Subgrupo o Grupo en que aspiren a ingresar.',d:'El sueldo de los funcionarios del grupo B2.'},correct:'c',why:{'c':'El art. 26 del EBEP establece que «las Administraciones públicas determinarán las retribuciones de los funcionarios en prácticas que, como mínimo, se corresponderán a las del sueldo del Subgrupo o Grupo, en el supuesto de que éste no tenga Subgrupo, en que aspiren a ingresar». Un funcionario que supera el proceso selectivo tiene derecho a percibir el sueldo de su subgrupo durante el curso selectivo.'}},
  {n:98,q:'¿Cuál de las siguientes proposiciones respecto de los trienios no es cierta?',o:{a:'Consisten en una cantidad igual para cada grupo por cada tres años de servicio en el Cuerpo o Escala, Clase o Categoría.',b:'Se computan independientemente del vínculo laboral que una al empleado público con la Administración.',c:'No se computan a efectos de trienios los períodos de prácticas.',d:'En su cómputo no se tiene en cuenta puesto de trabajo concreto desempeñado por el funcionario sino simplemente los servicios prestado en un grupo de titulación.'},correct:'c',why:{'c':'Se computan, a efectos de trienios, la totalidad de los servicios prestados desde que el funcionario comenzó a prestar sus servicios en la Administración e independientemente del vínculo laboral que les una, es decir no solo como funcionario de carrera sino también como eventual, interino o contratado laboral o administrativo, incluso durante el periodo de prácticas.'}},
  {n:99,q:'¿Qué conceptos retributivos no integran las pagas extraordinarias?',o:{a:'Todos los complementos y las horas extraordinarias.',b:'Los complementos que se refieran al grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos.',c:'Los complementos que se refieran al grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos así como los servicios extraordinarios prestados fuera de la jornada normal de trabajo.',d:'Los trienios, los complementos que se refieran al grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos y los servicios extraordinarios prestados fuera de la jornada normal de trabajo.'},correct:'c',why:{'c':'El EBEP regula en su art. 22.4 las pagas extraordinarias disponiendo que «serán dos, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las retribuciones complementarias, salvo aquellas a las que se refieren los apartados c) y d) del art. 24», es decir, excluyendo los complementos de rendimiento/interés y los servicios extraordinarios fuera de la jornada normal.'}},
  {n:100,q:'¿Cuándo se devengarán las pagas extraordinarias?',o:{a:'En julio y enero.',b:'En junio y en diciembre.',c:'En julio y diciembre.',d:'Cuando lo decida la Administración en donde preste sus servicios el funcionario.'},correct:'b',why:{'b':'El art. 23.2.c) de la LMRFP (derogado por el EBEP) establecía que las pagas extraordinarias se devengarían los meses de junio y diciembre. El EBEP no se pronuncia al respecto aunque se supone que se mantendrá este criterio en la normativa desarrolladora.'}},
  {n:101,q:'¿Cómo se denominan las retribuciones que retribuyen las características de los puestos de trabajo, la carrera profesional o el desempeño, rendimiento o resultados alcanzados por el funcionario?',o:{a:'Retribuciones básicas.',b:'Retribuciones complementarias.',c:'Retribuciones diferidas.',d:'Indemnizaciones.'},correct:'b',why:{'b':'Las retribuciones complementarias son las que retribuyen las características de los puestos de trabajo, la carrera profesional o el desempeño, rendimiento o resultados alcanzados por el funcionario. Su cuantía y estructura se establecerán por las correspondientes leyes de cada Administración pública, atendiendo a los factores previstos en el art. 24 EBEP.'}},
  {n:102,q:'¿Qué retribuciones complementarias regula el EBEP?',o:{a:'El complemento de destino y el complemento específico.',b:'El complemento de destino y el complemento de productividad.',c:'El complemento de destino, el complemento específico y el complemento de productividad.',d:'El EBEP no hace referencia a la denominación de ningún complemento en particular.'},correct:'d',why:{'d':'El EBEP no hace referencia a la denominación de ningún complemento aunque si bien desaparece del texto normativo su enumeración, los conceptos de complemento de destino, específico, o de productividad se originan por los mismos supuestos. Se introduce además uno nuevo: la progresión alcanzada dentro del sistema de carrera administrativa.'}},
  {n:103,q:'La cuantía y la estructura de las retribuciones complementarias de los funcionarios de la Administración local se establecerá:',o:{a:'Por la Administración del Estado.',b:'Por la Administración de la Comunidad Autónoma correspondiente.',c:'Por la Administración del Estado o de la Comunidad Autónoma.',d:'Por el Reglamento de Personal de la Corporación Local.'},correct:'c',why:{'c':'El EBEP en su art. 24 remite la cuantía y estructura de las retribuciones complementarias a las leyes reguladoras de la función pública de cada Administración. Para los funcionarios de la Administración Local será la normativa de la Comunidad Autónoma (aunque igualmente podría realizarse por la Administración del Estado) la que establecerá la estructura concreta delimitando sus máximos y mínimos.'}},
  {n:104,q:'¿Qué criterios orientadores se establecen en el EBEP para establecer la estructura de las retribuciones complementarias?',o:{a:'La progresión alcanzada por el funcionario dentro del sistema de carrera.',b:'La especial dificultad técnica, responsabilidad, dedicación, incompatibilidad exigible para el desempeño de determinados puestos o las condiciones en que se desarrolla el trabajo.',c:'El grado de interés, iniciativa o esfuerzo aplicado al desempeño del puesto de trabajo o el rendimiento o resultados obtenidos en el mismo, así como los servicios extraordinarios prestados fuera de la jornada normal de trabajo.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'El art. 24 EBEP establece factores orientadores para la estructura de las retribuciones complementarias: a) la progresión en la carrera, b) la especial dificultad técnica, responsabilidad, dedicación, incompatibilidad o condiciones de trabajo, c) el grado de interés, iniciativa o esfuerzo y el rendimiento o resultados, y d) los servicios extraordinarios fuera de la jornada normal. No son lista cerrada.'}},
  {n:105,q:'¿Qué concepto retributivo consiste en una cantidad fija que se percibe por el desempeño de un puesto de trabajo de un determinado nivel?',o:{a:'Complemento específico.',b:'Complemento de destino.',c:'Complemento de productividad.',d:'Complemento de progresión.'},correct:'b',why:{'b':'El complemento de destino se definía en el art. 23.3.a) de la LMRFP como el correspondiente al nivel del puesto que se desempeñe. Es un concepto retributivo de carácter obligatorio, de naturaleza objetiva, directamente vinculado al desempeño de un puesto de trabajo e independiente de quien sea el funcionario que lo desempeñe. Su cuantía es igual para cada nivel y se actualiza en los PGE.'}},
  {n:106,q:'La cuantía concreta del complemento de destino en la Administración Local será fijada con carácter general por:',o:{a:'La Comunidad Autónoma.',b:'El Alcalde.',c:'El Pleno de la Corporación.',d:'La Junta de Gobierno Local.'},correct:'c',why:{'c':'En el caso de los funcionarios de la Administración Local la cuantía global del complemento de destino será fijada por el Pleno de la Corporación (o la Junta de Gobierno Local en los municipios de gran población) dentro de los límites máximos y mínimos señalados por el Estado o la Comunidad Autónoma, asignando nivel a cada puesto de trabajo.'}},
  {n:107,q:'¿Qué retribución complementaria se refiere a la dedicación o responsabilidad?',o:{a:'El complemento de destino.',b:'El complemento de productividad.',c:'El complemento específico.',d:'Las gratificaciones.'},correct:'c',why:{'c':'El complemento específico «está destinado a retribuir las condiciones particulares de algunos puestos de trabajo en atención a su especial dificultad técnica, dedicación, incompatibilidad, responsabilidad, peligrosidad o penosidad». Es de naturaleza objetiva, vinculado al puesto y no a la persona que lo desempeñe, independientemente de quien sea su titular.'}},
  {n:108,q:'El complemento específico:',o:{a:'Es el mismo para todos los puestos de trabajo de un mismo nivel.',b:'Es el mismo para todos los puestos de trabajo asignados a un mismo Cuerpo, Escala o Grupo de titulación.',c:'Es un concepto retributivo que se puede asignar tantas veces como concurran cada una de las condiciones que lo puedan justificar.',d:'Es un concepto retributivo en el que todos los puestos de trabajo en que concurran las mismas circunstancias y con la misma intensidad han de tenerlo en la misma cuantía.'},correct:'d',why:{'d':'El complemento específico es de naturaleza objetiva: todos los puestos en que concurran las mismas circunstancias determinantes y con la misma intensidad han de tenerlo en la misma cuantía. No puede asignarse más de un complemento específico a cada puesto aunque concurra más de una condición particular. Las condiciones particulares son las tasadas por la Ley (dificultad técnica, dedicación, incompatibilidad, responsabilidad, peligrosidad, penosidad).'}},
  {n:109,q:'La cuantía del complemento específico se fija por:',o:{a:'El Pleno de la Corporación.',b:'El Alcalde.',c:'La Junta de Gobierno Local.',d:'El Pleno o la Junta de Gobierno Local.'},correct:'d',why:{'d':'Para la fijación del complemento específico en la Administración Local se exige con carácter previo una valoración del puesto de trabajo. Efectuada la valoración, el Pleno de la Corporación (o la Junta de Gobierno Local en las grandes ciudades), al aprobar la relación de puestos de trabajo, determina aquellos a los que les corresponde un complemento específico, señalando su respectiva cuantía.'}},
  {n:110,q:'El complemento de productividad no retribuirá:',o:{a:'El rendimiento.',b:'La iniciativa.',c:'El interés.',d:'La dedicación.'},correct:'d',why:{'d':'La finalidad del complemento de productividad es retribuir el especial rendimiento, la actividad extraordinaria y el interés o iniciativa con que el funcionario desempeñe su trabajo, no la dedicación, que se retribuye con el complemento específico. Se pretende incentivar al funcionario en el desarrollo concreto de su puesto de trabajo potenciando su eficacia.'}},
  {n:111,q:'¿Cuál de las siguientes retribuciones complementarias tiene carácter subjetivo o individual?',o:{a:'El complemento de destino.',b:'El complemento específico.',c:'El complemento de productividad.',d:'Todas estas retribuciones tienen carácter subjetivo.'},correct:'c',why:{'c':'El complemento de productividad es el único concepto retributivo de las retribuciones complementarias que es de carácter subjetivo o individual, ya que su finalidad es retribuir el especial rendimiento, la actividad extraordinaria y el interés o iniciativa con que el funcionario desempeñe su trabajo. El complemento específico y el de destino son de naturaleza objetiva, vinculados al puesto de trabajo.'}},
  {n:112,q:'¿Qué tipo de retribuciones no podrán ser fijas en su cuantía ni periódicas en su devengo?',o:{a:'El complemento de productividad.',b:'El complemento específico.',c:'Las pagas extraordinarias.',d:'Las indemnizaciones por razón del servicio.'},correct:'d',why:{'d':'El art. 28 del EBEP denomina «indemnizaciones por razón del servicio» a lo que el art. 23.4 de la LMRFP denominaba «gratificaciones por servicios extraordinarios». Su importe no es fijo ni periódica su percepción. Solo podrán ser reconocidas cuando no sea posible remunerar los servicios mediante las restantes retribuciones complementarias.'}},
  {n:113,q:'Las indemnizaciones por razón del servicio en la Administración local:',o:{a:'Se asignan libremente según los criterios fijados por el Alcalde.',b:'Es un concepto retributivo discrecional.',c:'Tienen carácter obligatorio para el funcionario que no puede rechazarlas libremente.',d:'Es un concepto retributivo no sujeto a límite máximo.'},correct:'b',why:{'b':'Las indemnizaciones por razón del servicio son un concepto retributivo discrecional, tanto en los requisitos para su concesión (aunque sí deba estar motivada) como en otros aspectos, como la cuantía. Las indemnizaciones por razón del servicio retribuyen servicios de carácter voluntario que el funcionario podrá rechazar libremente salvo circunstancias excepcionales.'}},
  {n:114,q:'¿Qué tipo de retribuciones complementarias no podrán percibir los funcionarios interinos?',o:{a:'Las vinculadas a las condiciones particulares del puesto.',b:'Las vinculadas a la productividad.',c:'Las vinculadas al rendimiento y a los servicios extraordinarios que realicen.',d:'Las vinculadas a la progresión alcanzada en la carrera.'},correct:'d',why:{'d':'El art. 25.1 del EBEP excluye expresamente la percepción por el funcionario interino del factor a) del art. 24, referente a la retribución complementaria ligada a «la progresión alcanzada en la carrera», ya que el interino no puede entrar en el sistema de carrera administrativa, patrimonio exclusivo de los funcionarios de carrera.'}},
  {n:115,q:'Los funcionarios interinos:',o:{a:'No podrán percibir trienios.',b:'Se les reconocerán los trienios correspondientes a los servicios prestados antes de la entrada en vigor del EBEP.',c:'Se les reconocerán los trienios correspondientes a los servicios prestados antes de la entrada en vigor del EBEP con efectos retributivos retroactivos.',d:'Ninguna respuesta es correcta.'},correct:'b',why:{'b':'El art. 25.2 del EBEP añadió que se reconocerán los trienios correspondientes a los servicios prestados antes de la entrada en vigor del EBEP, pero teniendo efectos retributivos únicamente a partir de la entrada en vigor del mismo. No son retroactivos.'}},
  {n:116,q:'De acuerdo con lo establecido en el EBEP los empleados públicos tienen derecho a participar en la consecución de los objetivos:',o:{a:'Que se fijen en los planes de empleo.',b:'Atribuidos a la unidad donde presten sus servicios.',c:'Para la consecución del interés general.',d:'Para hacer efectivos los principios de eficacia y eficiencia administrativa.'},correct:'b',why:{'b':'El art. 14.e) del EBEP reconoce a los empleados públicos el derecho individual «a participar en la consecución de los objetivos atribuidos a la unidad donde preste sus servicios y a ser informado por sus superiores de las tareas a desarrollar». Este derecho persigue una mayor implicación del empleado público en los objetivos planteados por la Administración.'}},
  {n:117,q:'En los procedimientos que se sigan ante cualquier orden jurisdiccional como consecuencia del ejercicio legítimo de sus funciones o cargos públicos los empleados públicos tendrán derecho:',o:{a:'A la defensa jurídica de la Administración.',b:'A la defensa jurídica y protección de la Administración.',c:'A la defensa jurídica, protección y representación de la Administración.',d:'A la defensa jurídica, protección, representación de la Administración sin que el funcionario tenga que designar un procurador.'},correct:'b',why:{'b':'El art. 14 f) EBEP reconoce a los empleados públicos el derecho a «la defensa jurídica y protección de la Administración Pública en los procedimientos que se sigan ante cualquier orden jurisdiccional como consecuencia del ejercicio legítimo de sus funciones o cargos públicos». El art. 141.2 del TRRL también recoge este derecho.'}},
  {n:118,q:'Según lo dispuesto en el artículo 14.g) del EBEP los empleados públicos tendrán derecho a la formación continua y a la actualización permanente de sus conocimientos y capacidades profesionales, que se deberá llevar a cabo:',o:{a:'Fuera del horario laboral.',b:'Durante el horario laboral.',c:'Preferentemente en horario laboral.',d:'Preferentemente durante los períodos vacacionales.'},correct:'c',why:{'c':'El art. 14.g) del EBEP se refiere al derecho de los empleados públicos «a la formación continua y a la actualización permanente de sus conocimientos y capacidades profesionales, preferentemente en horario laboral». La formación deberá tener carácter profesional y permanente, con posibilidad de convalidación por el Ministerio de Educación.'}},
  {n:119,q:'El artículo 14.h) del EBEP dispone que los empleados públicos tienen derecho al respeto de su intimidad, orientación sexual, propia imagen y dignidad en el trabajo, de manera que:',o:{a:'Distingue entre acoso sexual y acoso por razón de sexo.',b:'La violación de este derecho se tipifica como falta grave.',c:'No se tipifica en el régimen disciplinario la infracción de este derecho.',d:'Ninguna respuesta es correcta.'},correct:'a',why:{'a':'El art. 14.h) EBEP distingue entre acoso sexual y acoso por razón de sexo. La LO 3/2007 define el acoso sexual como comportamiento de naturaleza sexual que atenta contra la dignidad, y el acoso por razón de sexo como comportamiento realizado en función del sexo. El art. 95.2.b) EBEP contempla la discriminación y el acoso como falta muy grave.'}},
  {n:120,q:'¿Cuál de las siguientes respuestas sobre el acoso laboral no es cierta?',o:{a:'El EBEP no define el concepto de acoso laboral.',b:'El acoso laboral está tipificado como delito en el Código Penal.',c:'El acoso laboral se tipifica como falta muy grave pudiendo sancionarse incluso con la separación del servicio para los funcionarios de carrera.',d:'El acoso laboral de los funcionarios interinos no podrá comportar como sanción disciplinaria la revocación de su nombramiento.'},correct:'d',why:{'d':'El acoso laboral se tipifica como falta muy grave en el art. 95.2.o) del EBEP. Esta falta se podrá sancionar incluso con la separación del servicio, que en el caso de los funcionarios interinos SÍ podrá comportar la revocación de su nombramiento. Por tanto la afirmación de que no podrá comportarla es la incorrecta.'}},
  {n:121,q:'El artículo 14.i) del EBEP no hace referencia expresa al derecho de los empleados públicos a no ser discriminados por razón de:',o:{a:'Edad.',b:'Sexo.',c:'Minusvalía.',d:'Origen racial o étnico.'},correct:'c',why:{'c':'El art. 14.i del EBEP se refiere al derecho «a la no discriminación por razón de nacimiento, origen racial o étnico, género, sexo u orientación sexual, religión o convicciones, opinión, discapacidad, edad o cualquier otra condición o circunstancia personal o social». No se hace referencia a la «minusvalía», término anacrónico sustituido por «discapacidad» en el Código Penal en la reforma de 2015.'}},
  {n:122,q:'El derecho de los empleados públicos a la adopción de medidas que favorezcan la conciliación de la vida personal, familiar y laboral es un derecho:',o:{a:'Individual.',b:'Individual ejercido colectivamente.',c:'Retributivo.',d:'Ninguna respuesta es correcta.'},correct:'a',why:{'a':'El derecho de los empleados públicos a la adopción de medidas que favorezcan la conciliación de la vida personal, familiar y laboral se encuadra en el art. 14 del EBEP bajo la rúbrica «derechos individuales», en contraposición a los regulados en el art. 15 que se rubrican «derechos individuales ejercidos colectivamente».'}},
  {n:123,q:'El EBEP reconoce como derecho individual de los empleados públicos:',o:{a:'El derecho a la huelga.',b:'El derecho a la libertad de expresión.',c:'El derecho de reunión.',d:'El derecho a la libertad sindical.'},correct:'b',why:{'b':'El art. 14.k) del EBEP reconoce como derecho individual de los empleados públicos el derecho «a la libertad de expresión dentro de los límites del ordenamiento jurídico». El derecho a la huelga, la libertad sindical y el derecho de reunión son derechos individuales ejercidos colectivamente (art. 15 EBEP).'}},
  {n:124,q:'El artículo 14.l) del EBEP hace referencia al derecho de los empleados públicos a recibir protección eficaz en materia de:',o:{a:'Prevención de riesgos laborales.',b:'Seguridad y salud en el trabajo.',c:'Higiene laboral.',d:'Evaluación de los riesgos laborales relacionados con el puesto de trabajo.'},correct:'b',why:{'b':'El art. 14.l) del EBEP hace referencia al derecho de los empleados públicos «a recibir protección eficaz en materia de seguridad y salud en el trabajo». El art. 40 CE establece el deber de los poderes públicos de velar por la seguridad e higiene en el trabajo, siendo de obligada observancia la LPRL para las Administraciones Públicas en sus relaciones de carácter administrativo o estatutario.'}},
  {n:125,q:'De acuerdo con lo previsto en el EBEP los funcionarios tendrán derecho a disfrutar cada año natural de unas vacaciones retribuidas de:',o:{a:'Treinta días hábiles incluyendo los sábados.',b:'Como mínimo veintidós días hábiles sin incluir los sábados.',c:'Un mes.',d:'Treinta días hábiles sin incluir los sábados.'},correct:'b',why:{'b':'El art. 50 del EBEP establece que «los funcionarios públicos tendrán derecho a disfrutar como mínimo, durante cada año natural, de unas vacaciones retribuidas de veintidós días hábiles, o de los días que correspondan proporcionalmente si el tiempo de servicio durante el año fue menor». A los efectos, no se considerarán como días hábiles los sábados.'}},
  {n:126,q:'Los funcionarios de la Administración local tendrán derecho a disfrutar de las vacaciones previstas en:',o:{a:'La legislación de función pública de la Comunidad Autónoma.',b:'La legislación del Estado.',c:'La legislación de función pública de la Comunidad Autónoma teniendo la duración prevista en la legislación del Estado carácter de mínimo.',d:'La legislación de función pública de la Comunidad Autónoma, la legislación del Estado y el Reglamento de Personal de la Corporación.'},correct:'c',why:{'c':'El art. 142 del TRRL establece que «los funcionarios de la Administración Local tendrán derecho a... las vacaciones retribuidas previstas en la legislación sobre función pública de la Comunidad Autónoma respectiva y supletoriamente, en la aplicable a los funcionarios de la Administración del Estado». El panorama normativo sería el art. 50 EBEP como mínimo, mejorable por las Leyes de FP de las CCAA.'}},
  {n:127,q:'Los permisos a que tienen derecho los funcionarios públicos que se regulan en el EBEP tiene carácter de:',o:{a:'Obligatorios en su reconocimiento.',b:'Aplicables solo en defecto de legislación aplicable.',c:'Obligatorios en su reconocimiento si se regulan en el artículo 49 del EBEP.',d:'Obligatorios en su reconocimiento solo si su desarrollo se realiza a través de ley orgánica.'},correct:'c',why:{'c':'La redacción vigente del RDLeg 5/2015 suprime el carácter mínimo y supletorio mejorable del art. 48. Sin embargo, el art. 49 del EBEP sí establece una relación de permisos obligatorios en su reconocimiento por las Administraciones Públicas y con unas condiciones también mínimas, por tanto mejorables dentro del ámbito de sus competencias y previa negociación colectiva.'}},
  {n:128,q:'Los funcionarios de la Administración local tendrán derecho a los permisos previstos en:',o:{a:'La legislación de función pública de la Comunidad Autónoma.',b:'La legislación del Estado.',c:'La legislación de función pública de la Comunidad Autónoma o la legislación del Estado.',d:'La legislación de función pública de la Comunidad Autónoma, la legislación del Estado y el Reglamento de Personal de la Corporación.'},correct:'c',why:{'c':'El art. 142 del TRRL establece que los funcionarios de la Administración Local tendrán derecho a los permisos y licencias previstos en la legislación de la función pública de la Comunidad Autónoma respectiva y supletoriamente, en la aplicable a los funcionarios de la Administración del Estado. La Administración Local no puede mediante negociación colectiva modificar los supuestos, requisitos, efectos y duración de los permisos.'}},
  {n:129,q:'¿Todos los permisos recogidos en el EBEP son de aplicación directa a los empleados públicos de la Administración Local?',o:{a:'Sí, todos los permisos son aplicables directamente tanto al personal funcionario como al personal laboral al servicio de las entidades locales.',b:'Sí, todos los permisos son aplicables directamente al personal funcionario pero no al personal laboral al servicio de las entidades locales.',c:'No, ya que los permisos recogidos en el artículo 49 del EBEP son de aplicación directa al personal funcionario y laboral; y, los permisos establecidos en el artículo 48 lo serán «en defecto de legislación aplicable».',d:'No, ya que tanto los permisos recogidos en el artículo 49 del EBEP como los regulados en el artículo 48 son solo aplicables al personal funcionario y laboral de las entidades locales en defecto de legislación aplicable.'},correct:'c',why:{'c':'Atendiendo al art. 3 del EBEP, los funcionarios de las Entidades Locales están sometidos a la regulación básica estatal que contempla el EBEP, incluyendo los dos preceptos mencionados. Los permisos del art. 49 son obligatorios (mínimos mejorables), mientras que los del art. 48 se aplican «en defecto de legislación aplicable».'}},
  {n:130,q:'¿Cuál de los siguientes permisos cambia de denominación tras la modificación introducida por el Real Decreto-ley 6/2019, de 1 de marzo, en el EBEP?',o:{a:'El permiso por contraer matrimonio.',b:'El permiso fuerza mayor familiar.',c:'El permiso de paternidad por el nacimiento de un hijo.',d:'El permiso por traslado de domicilio.'},correct:'c',why:{'c':'El permiso por paternidad cambia de denominación tras la aprobación del Real Decreto-Ley 6/2019, de 1 de marzo, pasando ahora a denominarse «permiso del progenitor diferente de la madre biológica por nacimiento». El EBEP incorpora también el permiso por contraer matrimonio (apartado l) del art. 48) que antes no regulaba expresamente.'}},
  {n:131,q:'¿Cuál de los siguientes no es un permiso contemplado en el EBEP?',o:{a:'Por fallecimiento, accidente o enfermedad grave de un familiar dentro del primer grado de consanguinidad o afinidad.',b:'Por traslado de domicilio sin cambio de residencia.',c:'Para realizar funciones sindicales o de representación del personal.',d:'Para la preparación de exámenes finales y demás pruebas definitivas de aptitud.'},correct:'d',why:{'d':'El art. 48.1.d) del EBEP regula el permiso de los funcionarios públicos «para concurrir a exámenes finales y demás pruebas definitivas de aptitud, durante los días de su celebración». Se dice «concurrir» y no «preparar», por lo que un permiso para preparación de exámenes finales no está contemplado en el EBEP.'}},
  {n:132,q:'Sobre el permiso de los funcionarios públicos por fallecimiento, accidente o enfermedad de un familiar, ¿cuál de las siguientes opciones de respuesta no es cierta?',o:{a:'El familiar deberá estar comprendido en el primer o segundo grado de consanguinidad o afinidad.',b:'La duración del permiso depende de la localidad en la que se produce el fallecimiento, accidente o enfermedad.',c:'La enfermedad del familiar deberá tener la consideración de muy grave.',d:'Los días por los que se concederá el permiso serán días hábiles.'},correct:'c',why:{'c':'El art. 48.a) del EBEP se refiere a «enfermedad grave» y no «muy grave». El término «enfermedad grave» es un concepto jurídico indeterminado, por lo que su determinación debe realizarse caso por caso según la jurisprudencia. En algunos supuestos, la normativa autonómica ha establecido una escala en función de la gravedad.'}},
  {n:133,q:'Sobre el permiso de los funcionarios públicos por fallecimiento, accidente o enfermedad de un familiar, ¿cuál de las siguientes opciones de respuesta no es cierta?',o:{a:'Se trata de un permiso que está sometido a las necesidades organizativas de la Administración.',b:'No es prorrogable durante la situación de la enfermedad.',c:'Los sábados se consideran días hábiles.',d:'Ninguna respuesta es correcta.'},correct:'a',why:{'a':'Se trata de un permiso que no está sometido a las necesidades organizativas de la Administración, toda vez que rige el carácter imperativo del art. 48 EBEP «los funcionarios públicos tendrán...». El permiso ha de ser único y no es prorrogable durante la situación de enfermedad de familiar (STSJ Andalucía de 20 de octubre de 2000). Los sábados sí se consideran días hábiles.'}},
  {n:134,q:'Por traslado de domicilio sin cambio de residencia los funcionarios públicos tendrán derecho a un permiso:',o:{a:'De un día.',b:'De dos días.',c:'De tres días.',d:'Por el tiempo indispensable para efectuar el traslado.'},correct:'a',why:{'a':'De acuerdo con la letra b) del art. 48 del EBEP los funcionarios públicos tendrán derecho a un permiso de un día «por traslado de domicilio sin cambio de residencia». El cambio de hospedaje no confiere derecho al permiso, salvo que se efectúe mudanza de muebles o enseres.'}},
  {n:135,q:'Para realizar funciones sindicales o de representación del personal, ¿de qué permiso disponen los funcionarios públicos?',o:{a:'De un permiso de dos días hábiles de duración.',b:'De un permiso por el tiempo indispensable para realizar dichas funciones.',c:'De un permiso que dependerá de la localidad donde se realicen las funciones sindicales o de representación.',d:'De un permiso en los términos que se determine.'},correct:'d',why:{'d':'El art. 48.c) del EBEP dispone que los funcionarios públicos tendrán derecho a un permiso «para realizar funciones sindicales o de representación del personal, en los términos que se determine». La determinación de las condiciones podrá realizarse en el ámbito de la negociación colectiva.'}},
  {n:136,q:'Para la realización de exámenes prenatales y técnicas de preparación al parto, ¿cuál es la duración del permiso del que disponen las funcionarias?',o:{a:'Por el tiempo indispensable para su realización.',b:'Por el tiempo invertido en su desplazamiento.',c:'Dos días si las pruebas se realizan en la misma localidad de residencia de la funcionaria.',d:'Ninguna respuesta es correcta.'},correct:'a',why:{'a':'El art. 48.e) del EBEP dispone que los funcionarios públicos tendrán derecho a un permiso «por el tiempo indispensable para la realización de exámenes prenatales y técnicas de preparación al parto por las funcionarias embarazadas y, en los casos de adopción o acogimiento, para la asistencia a las preceptivas sesiones de información y preparación y para la realización de los preceptivos informes psicológicos y sociales previos a la declaración de idoneidad».'}},
  {n:137,q:'En relación con el permiso por lactancia, ¿cuál de las siguientes respuestas es falsa?',o:{a:'Se necesita para su disfrute por ambos trabajadores, que ambos progenitores trabajen.',b:'No puede transferirse su ejercicio al otro progenitor.',c:'Se podrá solicitar la sustitución del tiempo de lactancia por un permiso retribuido que acumule en jornadas completas el tiempo correspondiente.',d:'Se incrementará proporcionalmente en los casos de parto, adopción, guarda con fines de adopción o acogimiento múltiple.'},correct:'a',why:{'a':'El RDL 6/2019, de 1 de marzo, eliminó la necesidad de que ambos progenitores trabajen para disfrutar el permiso de lactancia, constituyéndose como un derecho individual de los funcionarios. Asimismo, no puede transferirse su ejercicio al otro progenitor, adoptante, guardador o acogedor.'}},
  {n:138,q:'¿Qué derecho se introduce en el EBEP como consecuencia de la publicación de la Ley Orgánica 3/2018 de 5 de diciembre, de Protección de Datos Personales?',o:{a:'El derecho a la intimidad en el uso de dispositivos digitales puestos a disposición del empleado público.',b:'El derecho a la intimidad frente al uso de dispositivos de videovigilancia y geolocalización.',c:'El derecho a la desconexión digital.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'El art. 14.j bis) del EBEP establece que los empleados públicos tienen derecho «a la intimidad en el uso de dispositivos digitales puestos a su disposición y frente al uso de dispositivos de videovigilancia y geolocalización, así como a la desconexión digital en los términos establecidos en la legislación vigente en materia de protección de datos personales y garantía de los derechos digitales».'}},
  {n:139,q:'La funcionaria o el funcionario tendrá derecho a ausentarse del trabajo durante un máximo de dos horas diarias percibiendo las retribuciones íntegras en caso de permiso:',o:{a:'Por lactancia.',b:'Por nacimiento de hijos prematuros.',c:'En los casos de parto múltiple.',d:'Por razones de guarda legal.'},correct:'b',why:{'b':'De acuerdo con el art. 48.g) del EBEP «por nacimiento de hijos prematuros o que por cualquier otra causa deban permanecer hospitalizados a continuación del parto, la funcionaria o el funcionario tendrá derecho a ausentarse del trabajo durante un máximo de dos horas diarias percibiendo las retribuciones íntegras». La madre funcionaria no podrá hacer uso de este permiso durante las seis semanas inmediatas posteriores al parto.'}},
  {n:140,q:'Por nacimiento de hijos prematuros o que por cualquier otra causa deban permanecer hospitalizados a continuación del parto, la funcionaria o el funcionario tendrá derecho:',o:{a:'A reducir su jornada de trabajo hasta un máximo de dos horas, con la disminución proporcional de sus retribuciones.',b:'A reducir su jornada de trabajo hasta un máximo de dos horas, sin que se puedan disminuir sus retribuciones.',c:'A reducir su jornada de trabajo hasta un máximo de dos horas, pudiéndose disminuir sus retribuciones solo en caso de permanecer el hijo hospitalizado.',d:'A ausentarse del trabajo durante una hora al día.'},correct:'a',why:{'a':'De acuerdo con el último inciso del art. 48.g) del EBEP, en este supuesto la funcionaria o el funcionario tendrán derecho «a reducir su jornada de trabajo hasta un máximo de dos horas, con la disminución proporcional de sus retribuciones». Este permiso deberá concederse mientras el hijo prematuro se encuentre en centro hospitalario.'}},
  {n:141,q:'El permiso por razones de guarda legal no se contempla cuando el funcionario tenga el cuidado directo de:',o:{a:'Algún menor de doce años.',b:'Persona mayor que requiera especial dedicación.',c:'Persona con discapacidad aunque desempeñe actividad retribuida.',d:'Persona con discapacidad que no desempeñe actividad retribuida.'},correct:'c',why:{'c':'Según el art. 48.h) del EBEP el permiso por razones de guarda legal se contempla «cuando el funcionario tenga el cuidado directo de algún menor de doce años, de persona mayor que requiera especial dedicación, o de una persona con discapacidad que no desempeñe actividad retribuida». Se exige, por tanto, que la persona con discapacidad no desempeñe actividad retribuida, por lo que si la desempeña no procede el permiso.'}},
  {n:142,q:'El permiso por razones de guarda legal se contempla cuando el funcionario tenga el cuidado de una persona mayor que requiera especial dedicación:',o:{a:'Independientemente de su grado de consanguinidad.',b:'Exigiendo que el familiar tenga hasta el segundo grado de consanguinidad o afinidad.',c:'Aunque el cuidado no se ejerza de forma directa.',d:'Si no existe ayuda de otros miembros del entorno familiar.'},correct:'a',why:{'a':'El art. 48.h) del EBEP en su primer inciso no indica ninguna precisión en relación a la situación de dependencia de las «personas mayores que requieran especial atención», con lo que puede entenderse que el funcionario tendrá derecho a solicitar la reducción de la jornada independientemente del grado de dependencia del familiar. El cuidado directo sí se exige expresamente.'}},
  {n:143,q:'El permiso por razones de guarda legal de un familiar exige el segundo grado de consanguinidad o afinidad:',o:{a:'En cualquier caso.',b:'Para el cuidado directo de un familiar que por razones de edad, accidente o enfermedad no pueda valerse por sí mismo y que no desempeñe actividad retribuida.',c:'Para el cuidado directo de un familiar que por razones de edad, accidente o enfermedad no pueda valerse por sí mismo aún desempeñando actividad retribuida.',d:'De manera que también se incluyen las relaciones derivadas de las parejas de hecho y las estructuras familiares derivadas de la separación, divorcio y viudedad.'},correct:'b',why:{'b':'El art. 48.h) del EBEP en su último inciso dispone que «tendrá el mismo derecho el funcionario que precise encargarse del cuidado directo de un familiar, hasta el segundo grado de consanguinidad o afinidad, que por razones de edad, accidente o enfermedad no pueda valerse por sí mismo y que no desempeñe actividad retribuida».'}},
  {n:144,q:'Por ser preciso atender el cuidado de un familiar de primer grado, el funcionario tendrá derecho:',o:{a:'A obtener un permiso.',b:'A solicitar un permiso.',c:'A disfrutar de un permiso.',d:'Ninguna respuesta es correcta.'},correct:'b',why:{'b':'El art. 48.i) del EBEP se refiere al derecho al permiso del funcionario «por ser preciso atender el cuidado de un familiar de primer grado, el funcionario tendrá derecho a solicitar una reducción de hasta el cincuenta por ciento de la jornada laboral, con carácter retribuido, por razones de enfermedad muy grave y por el plazo máximo de un mes». Solo se concede el derecho a «solicitar», no el disfrute garantizado.'}},
  {n:145,q:'¿Se puede disfrutar íntegramente del permiso para atender el cuidado de un familiar de primer grado por más de un titular si el sujeto causante fuese el mismo?',o:{a:'No.',b:'Sí, sin que en este caso se respete el límite máximo de un mes.',c:'Sí, aunque respetando el límite máximo de un mes.',d:'No, excepto que se realice de forma no retribuida.'},correct:'a',why:{'a':'El art. 48.i) del EBEP en su último inciso dice que «si hubiera más de un titular de este derecho por el mismo hecho causante, el tiempo de disfrute de esta reducción se podrá prorratear entre los mismos, respetando en todo caso, el plazo máximo de un mes». Se impide así el disfrute íntegro de este derecho por más de un titular si el sujeto causante fuese el mismo.'}},
  {n:146,q:'Para acudir a la citación de un Juzgado el funcionario público:',o:{a:'No dispone de ningún permiso.',b:'Dispone de un permiso por tiempo indispensable para el cumplimiento de este deber.',c:'No dispone de un permiso, sino de una licencia.',d:'Dispone de un permiso durante el día en que esté citado.'},correct:'b',why:{'b':'Según el art. 48.j) del EBEP los funcionarios públicos disponen de un permiso «por tiempo indispensable para el cumplimiento de un deber inexcusable de carácter público». Las normas autonómicas entienden como deberes inexcusables las citaciones de Juzgados, Comisaría, Gobierno civiles o militares, expedición o renovación del DNI o pasaporte, etc.'}},
  {n:147,q:'Por asuntos particulares el funcionario público tendrá derecho a un permiso de:',o:{a:'Tres días al año.',b:'Cuatro días al año.',c:'Cinco días al año.',d:'Seis días al año.'},correct:'d',why:{'d':'El art. 48.k) del nuevo Texto Refundido del EBEP establece que la duración del permiso por asuntos particulares es de seis días al año. El Real Decreto Ley 20/2012 redujo de seis a tres los días, pero la redacción vigente del RDLeg 5/2015 restableció los seis días. El funcionario puede disfrutar los días por las razones particulares que quiera sin necesidad de justificarlas.'}},
  {n:148,q:'¿Cuál de las siguientes proposiciones con respecto al permiso por asuntos particulares no es cierta?',o:{a:'Su duración puede ser ampliada por las Comunidades Autónomas.',b:'La duración de este permiso está subordinada a que se hayan prestado servicios durante un mínimo de tiempo.',c:'No pueden disfrutarse uniéndolos al período de vacaciones.',d:'El funcionario deberá justificar la motivación para su obtención.'},correct:'d',why:{'d':'Por tratarse de asuntos particulares, el funcionario no deberá justificarlos en su solicitud. La duración es susceptible de ampliación por las CCAA (oscila entre 6 y 10 días según normativas autonómicas). La duración está subordinada a haber prestado servicios durante un año (si no, se prorratea). La STC 9/2016 ha zanjado la cuestión sobre su acumulación al período vacacional.'}},
  {n:149,q:'¿Cuál es la duración del permiso por matrimonio?',o:{a:'Dos semanas.',b:'Quince días.',c:'Dieciséis días.',d:'Veinte días.'},correct:'b',why:{'b':'La letra l) del art. 48 del EBEP introdujo el permiso por matrimonio de quince días. La duración ha de computarse en días naturales. El motivo justificativo del permiso es el vínculo marital (heterosexual u homosexual, permitido tras la Ley 13/2005), de modo que las uniones meramente religiosas o fácticas resultan inhábiles para obtener el derecho.'}},
  {n:150,q:'En el año 2011 se incorporó al EBEP un nuevo supuesto de permiso relacionado con la vida familiar ¿cuál es?',o:{a:'El permiso por razón de violencia de género sobre la mujer funcionaria.',b:'El permiso de paternidad por el nacimiento de un hijo.',c:'El permiso por cuidado de hijo menor afectado por cáncer u otra enfermedad grave.',d:'El permiso por nacimiento de hijos prematuros.'},correct:'c',why:{'c':'La Ley 39/2010, de Presupuestos Generales del Estado para el año 2011, introdujo una modificación en el EBEP incorporando en su art. 49 un nuevo apartado e) referente al cuidado, durante la hospitalización y tratamiento continuado, del hijo menor de edad afectado por cáncer (tumores malignos, melanomas y carcinomas) o por cualquier otra enfermedad grave.'}},
  {n:151,q:'El artículo 49.a) del EBEP hace referencia:',o:{a:'Al permiso por nacimiento para la madre biológica.',b:'Al permiso de paternidad.',c:'Al permiso de maternidad y paternidad.',d:'Al permiso por parto.'},correct:'a',why:{'a':'El art. 49.a) del EBEP hace referencia al permiso «por nacimiento para la madre biológica», especificando que «tendrá una duración de dieciséis semanas, de las cuales las seis semanas inmediatas posteriores al parto serán en todo caso de descanso obligatorio e ininterrumpidas». La tradicional denominación «permiso por maternidad» ha sido sustituida por el RDL 6/2019.'}},
  {n:152,q:'La duración del permiso por nacimiento para la madre biológica será de dieciséis semanas:',o:{a:'Sin posibilidad de que pueda ser ampliado en ningún supuesto.',b:'Con la posibilidad de que se incremente solamente en el caso de discapacidad del hijo.',c:'Con la posibilidad de que se incremente en el caso de discapacidad del hijo y en el caso de parto múltiple.',d:'Sin la posibilidad de que pueda ser ampliado cuando ambos cónyuges soliciten su disfrute.'},correct:'c',why:{'c':'El art. 49.a) del EBEP dispone que «este permiso se ampliará en dos semanas más en el supuesto de discapacidad del hijo o hija y, por cada hijo o hija a partir del segundo en los supuestos de parto múltiple, una para cada uno de los progenitores». En casos de parto prematuro con hospitalización, se amplía en tantos días como el neonato esté hospitalizado, con un máximo de trece semanas adicionales.'}},
  {n:153,q:'¿Cuál de las siguientes proposiciones respecto del permiso por nacimiento para la madre biológica es cierta?',o:{a:'Podrá disfrutarse a jornada completa.',b:'Podrá disfrutarse a tiempo parcial.',c:'Podrá disfrutarse simultáneamente por el padre y la madre.',d:'No es ampliable bajo ninguna circunstancia.'},correct:'d',why:{'d':'De acuerdo con el art. 49.a) del EBEP, la afirmación de que el permiso no es ampliable bajo ninguna circunstancia es la que no resulta cierta en el sentido de que sí puede ampliarse (discapacidad del hijo, parto múltiple, hospitalización del neonato). Las opciones a) y b) también son ciertas pues puede disfrutarse a jornada completa o a tiempo parcial cuando las necesidades del servicio lo permitan.'}},
  {n:154,q:'¿En qué supuesto el permiso por adopción o acogimiento genera además otro permiso de hasta dos meses de duración?',o:{a:'En el supuesto de discapacidad del menor adoptado o acogido.',b:'En el supuesto en que el adoptado o acogido sea menor de seis años.',c:'En el supuesto de adopción o acogimiento internacional.',d:'Si fuera necesario el desplazamiento previo de los progenitores al país de origen del adoptado.'},correct:'d',why:{'d':'El art. 49.b) del EBEP dispone que «si fuera necesario el desplazamiento previo de los progenitores al país de origen del adoptado, en los casos de adopción o acogimiento internacional, se tendrá derecho, además, a un permiso de hasta dos meses de duración, percibiendo durante este periodo exclusivamente las retribuciones básicas».'}},
  {n:155,q:'Las faltas de asistencia al trabajo de las funcionarias víctimas de violencia de género:',o:{a:'Se sancionarán de acuerdo con el régimen disciplinario.',b:'Podrán tener la consideración de justificadas.',c:'En ningún supuesto podrán ser retribuidas.',d:'Ninguna respuesta es correcta.'},correct:'b',why:{'b':'El art. 49.d) del EBEP establece que «las faltas de asistencia de las funcionarias víctimas de violencia de género, totales o parciales, tendrán la consideración de justificadas por el tiempo y en las condiciones en que así lo determinen los servicios sociales de atención o de salud según proceda». Tales ausencias se regulan como faltas justificadas y, por tanto, retribuidas.'}},
  {n:156,q:'¿Quién debe justificar las faltas de asistencia al trabajo de las víctimas de violencia de género?',o:{a:'La policía, mediante un informe.',b:'Los servicios sociales de atención o de salud.',c:'El superior jerárquico de la funcionaria víctima de violencia de género.',d:'El informe del Ministerio Fiscal que indique la existencia de indicios sobre la condición de haber sufrido violencia de género.'},correct:'b',why:{'b':'Según el art. 49.d) del EBEP en su primer inciso, las ausencias al trabajo, para considerarse justificadas, deben estar debidamente acreditadas por los servicios sociales de atención o servicios de salud. Las funcionarias deberán entregar el certificado que les hayan expedido uno u otro servicio, en el que se constate que su situación física o psicológica justifica las ausencias o faltas de puntualidad.'}},
  {n:157,q:'Las funcionarias víctimas de violencia sobre la mujer tendrán derecho:',o:{a:'A la reducción de la jornada sin disminución proporcional de la retribución.',b:'A la reordenación del tiempo de trabajo que ella solicite.',c:'A la reordenación del tiempo de trabajo que la Administración establezca.',d:'A una reducción del cincuenta por ciento de la jornada laboral.'},correct:'c',why:{'c':'El art. 49.d) del EBEP dispone que las funcionarias víctimas de violencia tendrán derecho a la reducción de la jornada con disminución proporcional de la retribución, o la reordenación del tiempo de trabajo, «en los términos que para estos supuestos establezca el plan de igualdad de aplicación o, en su defecto, la Administración Pública competente en cada caso». La funcionaria mantendrá retribuciones íntegras si reduce su jornada en un tercio o menos.'}},
  {n:158,q:'El artículo 49.e) del EBEP se refiere al permiso por cuidado de hijo menor afectado:',o:{a:'Por cualquier enfermedad grave.',b:'Por cáncer.',c:'Por cáncer u otra enfermedad grave.',d:'Por cáncer u otra enfermedad grave que requiera hospitalización.'},correct:'d',why:{'d':'El art. 49.e) EBEP regula la reducción de jornada para el cuidado de menores afectados por cáncer (melanoma, carcinoma o tumores malignos) o por cualquier otra enfermedad grave, que implique un ingreso hospitalario de larga duración y requiera la necesidad de su atención directa, continua y permanente. Se considera ingreso hospitalario de larga duración la continuación del tratamiento médico o cuidado del menor en el domicilio.'}},
  {n:159,q:'¿Cuál de las siguientes proposiciones respecto del permiso por cuidado de hijo menor afectado por cáncer u otra enfermedad grave no es cierta?',o:{a:'El hijo debe ser menor de dieciséis años.',b:'Para su disfrute es necesario que ambos progenitores trabajen.',c:'El permiso es retribuido íntegramente.',d:'La reducción de la jornada de trabajo será de al menos la mitad de su duración.'},correct:'a',why:{'a':'Según el art. 49.e) del EBEP en su primer inciso el cuidado debe ser del hijo «menor de edad... como máximo, hasta que el menor cumpla los 18 años». Por tanto, el hijo debe ser menor de 18 años y no de 16 como incorrectamente indica la opción a). Para su disfrute es necesario que ambos progenitores trabajen y la reducción ha de ser como mínimo de la mitad de la jornada.'}},
  {n:160,q:'¿Quiénes, como consecuencia de la actividad terrorista, tienen derecho a la reducción de la jornada o a la reordenación del tiempo de trabajo?',o:{a:'Los funcionarios que hayan sufrido daños físicos o psíquicos como consecuencia de la actividad terrorista.',b:'El cónyuge o persona con análoga relación de afectividad de dichos funcionarios, aunque no sea funcionario.',c:'Los hijos de los heridos, aunque no ostenten la condición de funcionarios.',d:'Los hijos de los fallecidos, aunque no ostenten la condición de funcionarios.'},correct:'a',why:{'a':'El art. 49.f) del EBEP dispone el derecho a reducción de jornada o reordenación del tiempo de trabajo para los funcionarios que hayan sufrido daños físicos o psíquicos como consecuencia de la actividad terrorista, su cónyuge o persona con análoga relación de afectividad, y los hijos de los heridos y fallecidos, «siempre que ostenten la condición de funcionarios». El titular primario es el funcionario que sufrió daños.'}},
  {n:161,q:'¿Cuál de los siguientes derechos sindicales está prohibido a los miembros de la Policía Local?',o:{a:'El derecho a constituir organizaciones sindicales.',b:'El derecho a afiliarse a organizaciones sindicales.',c:'El derecho a la acción sindical.',d:'El derecho a la huelga.'},correct:'d',why:{'d':'El art. 6.8 de la LO 2/1986, de 13 de marzo, de Fuerzas y Cuerpos de Seguridad, dispone que «los miembros de las Fuerzas y Cuerpos de Seguridad no podrán ejercer en ningún caso el derecho de huelga, ni acciones substitutivas del mismo o concertadas con el fin de alterar el normal funcionamiento de los servicios». Los cuerpos de la Policía Local tienen reconocidos los demás derechos sindicales.'}},
  {n:162,q:'El código de conducta de los empleados públicos que regula el EBEP:',o:{a:'No es aplicable a los funcionarios de la Administración local.',b:'Se aplicará a los funcionarios de la Administración de forma supletoria y en ausencia de regulación autonómica.',c:'Se aplicará plenamente a los funcionarios de la Administración local.',d:'Se aplicará solamente a los funcionarios de la Administración local de habilitación nacional.'},correct:'c',why:{'c':'Los deberes de los empleados públicos y el Código de conducta que se regula en el Capítulo VI del Título III del EBEP no solo se aplica a todos los empleados públicos sino que además se aplica plenamente (Disposición Adicional Primera) a todos los empleados y directivos de las entidades del sector público estatal, autonómico y local.'}},
  {n:163,q:'El código de conducta de los empleados públicos que se regula en el EBEP se desglosa en dos clases de principios que se denominan:',o:{a:'Principios de actuación y principios de conducta.',b:'Principios éticos y principios de conducta.',c:'Principios éticos y principios de actuación.',d:'Principios en su relación con los ciudadanos y principios en su entorno de trabajo.'},correct:'b',why:{'b':'El código de conducta regulado en el EBEP no es un código unitario sino que se desglosa en dos amplias relaciones: «principios éticos» que se regulan en el art. 53 y «principios de conducta» regulados en el art. 54. Su mayor valor radica en el ensayo de sistematización de tales principios.'}},
  {n:164,q:'Según lo dispuesto en el artículo 53.1 del EBEP los empleados públicos:',o:{a:'Acatarán la Constitución.',b:'Guardarán fidelidad a la Constitución y al resto del ordenamiento jurídico.',c:'Acatarán la Constitución y el resto del ordenamiento jurídico.',d:'Respetarán la Constitución y el resto de normas que integran el ordenamiento jurídico.'},correct:'d',why:{'d':'El art. 53.1 del EBEP dispone que «los empleados públicos respetarán la Constitución y el resto de normas que integran el ordenamiento jurídico». No se trata de un deber de carácter ideológico que exija fidelidad, sino que se requiere que el empleado público ajuste su actuación profesional a las reglas de comportamiento que constituyen el código de conducta.'}},
  {n:165,q:'Según lo dispuesto en el artículo 53.b) del EBEP, la actuación de los empleados públicos perseguirá:',o:{a:'El respeto al ordenamiento jurídico.',b:'La satisfacción de los intereses generales de los ciudadanos.',c:'El respeto a los derechos fundamentales.',d:'La independencia política.'},correct:'b',why:{'b':'El art. 53.2 del EBEP reitera expresamente que la actuación de los empleados públicos «perseguirá la satisfacción de los intereses generales de los ciudadanos y se fundamentará en consideraciones objetivas orientadas hacia la imparcialidad y el interés común, al margen de cualquier otro factor que exprese posiciones personales, familiares, corporativas, clientelares o cualesquiera otras».'}},
  {n:166,q:'Los empleados públicos ajustarán su actuación a los principios de:',o:{a:'Lealtad y buena fe con la Administración en la que presten sus servicios.',b:'Eficacia y eficiencia con la Administración en la que presten servicios.',c:'Transparencia y eficacia con la Administración en la que presten sus servicios.',d:'Todas las respuestas son correctas.'},correct:'a',why:{'a':'El art. 53.3 del EBEP dispone que los empleados públicos «ajustarán su actuación a los principios de lealtad y buena fe con la Administración en la que presten sus servicios, y con sus superiores, compañeros, subordinados y con los ciudadanos».'}},
  {n:167,q:'A los empleados públicos se les impone un deber respecto de aquellos asuntos en los que tengan un interés personal, ¿cómo se denomina a este deber?',o:{a:'Deber de recusación.',b:'Deber de abstención.',c:'Deber de neutralidad.',d:'Deber de imparcialidad.'},correct:'b',why:{'b':'El art. 53.5 del EBEP establece el deber de abstención: los empleados públicos «se abstendrán en aquellos asuntos en los que tengan un interés personal, así como de toda actividad privada o interés que pueda suponer un riesgo de plantear conflictos de intereses con su puesto público». Se aplica conforme al art. 23 de la Ley 40/2015 de Régimen Jurídico del Sector Público.'}},
  {n:168,q:'Cuando existe una disfunción entre las obligaciones públicas y el interés privado que puede indebidamente influir en el cumplimiento de las obligaciones y responsabilidades del empleado público se dice que existe:',o:{a:'Una incompatibilidad no declarada.',b:'Un conflicto de intereses.',c:'Una falta de transparencia.',d:'Un tráfico de influencias.'},correct:'b',why:{'b':'El conflicto de intereses se define como un conflicto entre obligaciones públicas e interés privado que puede indebidamente influir en el cumplimiento de sus obligaciones y responsabilidades. El art. 53.6 del EBEP dispone que los empleados públicos «no contraerán obligaciones económicas ni intervendrán en operaciones financieras... cuando puedan suponer un conflicto de intereses con las obligaciones de su puesto público».'}},
  {n:169,q:'Según dispone el artículo 53.7 del EBEP, los empleados públicos "no aceptarán ningún trato de favor o situación que implique privilegio o ventaja injustificada, por parte de personas físicas o entidades privadas", ¿qué delito se tipifica en el código penal a fin de castigar quien incurra en dicha conducta?',o:{a:'El delito de malversación de fondos públicos.',b:'El delito de tráfico de influencias.',c:'El delito de cohecho.',d:'El delito de prevaricación administrativa.'},correct:'c',why:{'c':'El Código Penal en su art. 422 (modificado por la LO 5/2010) dispone que «la autoridad o funcionario público que, en provecho propio o de un tercero, admitiera, por sí o por persona interpuesta, dádiva o regalo que le fueren ofrecidos en consideración a su cargo o función, incurrirá en la pena de prisión de seis meses a un año y suspensión de empleo y cargo público de uno a tres años». Se trata del delito de cohecho.'}},
  {n:170,q:'Según lo dispuesto en el artículo 53.8 del EBEP, ¿cuál de los siguientes no es un principio de acuerdo con el cual deban actuar los empleados públicos?',o:{a:'Eficacia.',b:'Economía.',c:'Obediencia debida.',d:'Eficiencia.'},correct:'c',why:{'c':'El art. 53.8 del EBEP dispone que los empleados públicos «actuarán de acuerdo con los principios de eficacia, economía y eficiencia, y vigilarán la consecución del interés general y el cumplimiento de los objetivos de la organización». No se menciona aquí el principio de obediencia debida.'}},
  {n:171,q:'Los empleados públicos no influirán en la agilización o resolución de trámites administrativos:',o:{a:'Sin causa justa que lo justifique.',b:'Cuando ello comporte un privilegio en beneficio de los titulares de los cargos públicos o su entorno familiar y social inmediato.',c:'Cuando suponga un menoscabo de los intereses de terceros.',d:'Todas las respuestas son correctas.'},correct:'d',why:{'d':'El art. 53.9 EBEP establece que los empleados públicos «no influirán en la agilización o resolución de trámite o procedimiento administrativo sin justa causa y, en ningún caso, cuando ello comporte un privilegio en beneficio de los titulares de los cargos públicos o su entorno familiar y social inmediato o cuando suponga un menoscabo de los intereses de terceros».'}},
  {n:172,q:'Los empleados públicos, según lo dispuesto en el artículo 53.11 del EBEP, ejercerán sus atribuciones según el principio de dedicación al servicio público absteniéndose:',o:{a:'De cualesquiera conductas que comprometan la neutralidad en el ejercicio de los servicios públicos.',b:'De entrar en un conflicto de intereses con otros empleados públicos.',c:'De guardar secreto de su actuación.',d:'De influir en la agilización o resolución de los trámites o procedimientos administrativos.'},correct:'a',why:{'a':'En el art. 53.11 del EBEP se describe que los empleados públicos ejercerán sus atribuciones absteniéndose de conductas «que comprometan la neutralidad en el ejercicio de los servicios públicos». Guarda relación con el deber de diligencia del art. 53.10 y con el principio de objetividad en el desempeño de su función.'}},
  {n:173,q:'El EBEP establece para los empleados públicos el deber de guardar secreto:',o:{a:'De las materias clasificadas.',b:'De las materias clasificadas u otras cuya difusión esté prohibida legalmente.',c:'De las materias clasificadas u otras cuya difusión esté prohibida legalmente así como sobre aquellos asuntos que conozcan por razón de su cargo.',d:'De las materias clasificadas u otras cuya difusión esté prohibida legalmente así como sobre aquellos asuntos que conozcan por razón de su cargo y de las que pueda hacer uso para beneficio propio o de terceros.'},correct:'c',why:{'c':'El art. 53.12 del EBEP establece que los empleados públicos «guardarán secreto de las materias clasificadas u otras cuya difusión esté prohibida legalmente, y mantendrán la debida discreción sobre aquellos asuntos que conozcan por razón de su cargo, sin que puedan hacer uso de la información obtenida para beneficio propio o de terceros, o en perjuicio del interés público».'}},
  {n:174,q:'La infracción del deber de guardar secreto de los empleados públicos:',o:{a:'Constituye falta leve.',b:'Constituye falta grave.',c:'Constituye falta muy grave.',d:'Constituye falta muy grave y delito.'},correct:'d',why:{'d':'Para el EBEP la infracción del deber de guardar secreto puede constituir falta muy grave (art. 95 EBEP): «publicación o utilización indebida de documentación e información» o «negligencia en la custodia de secretos oficiales». Además puede constituir infracción penal a tenor del art. 417 del Código Penal: «la autoridad o funcionario público que revelare secretos... incurrirá en la pena de doce a dieciocho meses e inhabilitación especial».'}},
  {n:175,q:'El deber de guardar secreto de los empleados públicos:',o:{a:'Afecta solamente al período en que el empleado mantenga su condición de funcionario.',b:'Se mantendrá ante actuaciones ilegales, o delictivas que el empleado público tenga conocimiento por razón de su cargo.',c:'Vincula al funcionario incluso cuando cesa en su condición de tal.',d:'Se sanciona administrativamente incluso para funcionarios que hubieran perdido la condición de funcionario público.'},correct:'c',why:{'c':'Debe entenderse que el deber de sigilo y secreto profesional vincula al funcionario incluso cuando cesa en su condición de tal. Así se recoge en la jurisprudencia y expresamente para la función pública comunitaria (Reglamento núm. 259/1968) cuyo art. 17 establece que «el funcionario seguirá estando sujeto a esta obligación tras el cese de sus funciones». Sin embargo, salvo delito, ninguna sanción administrativa puede imponerse a quien perdió la condición de funcionario.'}},
  {n:176,q:'Según lo dispuesto en el artículo 54.2 del EBEP el desempeño de las tareas correspondientes al puesto de trabajo de los empleados públicos se realizará:',o:{a:'Con atención y respeto a los ciudadanos.',b:'Con atención y respeto a sus superiores.',c:'Con atención y respeto a los restantes empleados públicos.',d:'De forma diligente y cumpliendo la jornada y el horario establecidos.'},correct:'d',why:{'d':'Según el art. 54.2 del EBEP «el desempeño de las tareas correspondientes a su puesto de trabajo se realizará de forma diligente y cumpliendo la jornada y el horario establecidos». El art. 54.1 añade que «tratarán con atención y respeto a los ciudadanos, a sus superiores y a los restantes empleados públicos».'}},
  {n:177,q:'Los empleados públicos deberán obedecer las instrucciones y órdenes profesionales de los superiores salvo.',o:{a:'Que deban abstenerse por razón de sexo.',b:'Que constituyan una infracción manifiesta del ordenamiento jurídico.',c:'Que infrinjan el principio de lealtad y buena fe con la Administración.',d:'Que sean contrarias al respeto a los derechos fundamentales y libertades públicas.'},correct:'b',why:{'b':'El art. 54.3 del EBEP establece que los empleados públicos «obedecerán las instrucciones y órdenes profesionales de los superiores, salvo que constituyan una infracción manifiesta del ordenamiento jurídico, en cuyo caso las pondrán inmediatamente en conocimiento de los órganos de inspección procedentes». Este deber de obediencia se fundamenta en el principio de jerarquía (art. 103.3 CE).'}},
  {n:178,q:'Es un principio de conducta de los empleados públicos:',o:{a:'Informar a los ciudadanos sobre aquellas materias o asuntos que tengan derecho a conocer.',b:'Informar a los interesados del estado de su procedimiento.',c:'Informar a los ciudadanos de los derechos y deberes en sus relaciones con la Administración.',d:'Todas las respuestas son correctas.'},correct:'a',why:{'a':'El art. 54.4 EBEP especifica que los empleados públicos «informarán a los ciudadanos sobre aquellas materias o asuntos que tengan derecho a conocer, y facilitarán el ejercicio de sus derechos y el cumplimiento de sus obligaciones». Este principio de conducta se vincula directamente con la trasparencia y la comunicación con los ciudadanos.'}},
  {n:179,q:'Los empleados públicos administrarán los recursos y bienes públicos:',o:{a:'Con eficacia.',b:'Con austeridad.',c:'Con transparencia.',d:'Con eficiencia.'},correct:'b',why:{'b':'El art. 54.5 del EBEP dispone que los empleados públicos «administrarán los recursos y bienes públicos con austeridad, y no utilizarán los mismos en provecho propio o de personas allegadas. Tendrán, asimismo, el deber de velar por su conservación». Este principio supone la síntesis de comportamientos asentados sobre valores de integridad, dedicación al servicio público, ejemplaridad y honradez.'}},
  {n:180,q:'¿En qué supuesto deberán garantizar los empleados públicos la atención al ciudadano en la lengua que lo solicite?',o:{a:'En cualquier caso.',b:'Siempre que el ciudadano lo solicite por escrito.',c:'Siempre que sea oficial en el territorio.',d:'Siempre que se trate de lenguas cooficiales.'},correct:'c',why:{'c':'El art. 54.11 del EBEP dispone que los empleados públicos «garantizarán la atención al ciudadano en la lengua que lo solicite siempre que sea oficial en el territorio». La STC 82/1986 establece que «es oficial una lengua, independientemente de su realidad y peso como fenómeno social, cuando es reconocida por los poderes públicos como medio normal de comunicación en y entre ellos y en su relación con los sujetos privados con plena validez y efectos jurídicos».'}}
];
